-- 172: the shelf tells the truth.
--
-- The 44 parent lesson stubs become real lessons. Every deck follows the
-- proven seven slide arc (title, objective, teach, practise, prove, DiGi
-- close), each one teaches a named move a family can use the same day, and
-- the same deck plays in the child's own app with the grown up script
-- channel stripped, so the shelf is finished for both sides at once.
-- Authored 8 August 2026 against the passport grid: five stages, nine
-- categories. Guarded on status = 'stub' so a lesson edited since keeps
-- its edits.

update lessons set
  slides = '[{"body": "A ten minute lesson for you and your child, about how AI learns and why it sometimes gets things wrong.", "type": "title", "phase": "starter", "title": "What is a robot brain?", "script": "Ask out loud: have you ever asked a voice assistant or a chatbot something? What did it say back? Today we find out how that robot brain actually works, and when to trust it.", "eyebrow": "Builder · Ages 8 to 10 · AI and you", "minutes": 1}, {"why": "AI sounds sure of itself even when it is wrong. Once you know how it learns, you know exactly when to check.", "type": "objective", "gains": ["I know AI learns from examples people gave it", "I know AI can sound sure and still be wrong", "I have the double check for anything important"], "phase": "starter", "minutes": 1, "outcome": "I can explain how AI learns from examples, and double check what it tells me."}, {"body": "AI is not magic, and it does not think like you. People showed it millions of examples, and it learnt patterns from them. When you ask it something, it guesses the most likely answer from those patterns. Often a good guess. Sometimes a wrong one.", "type": "concept", "emoji": "🤖", "phase": "teach", "script": "Try this comparison: it is like a parrot that has heard millions of conversations. It can say very clever sounding things without knowing if they are true. Ask your child: can something sound clever and still be wrong?", "heading": "A brain made of examples", "minutes": 2}, {"body": "AI never says I am not sure. It just answers, in the same confident voice, right or wrong. So we use the double check. If it matters, check it somewhere else: a book, a trusted site, or a grown up who knows. Fun questions can stay fun. Important ones get the double check.", "type": "concept", "emoji": "✅", "phase": "teach", "script": "Agree together what counts as important: homework, anything about health, anything about a person, anything you would repeat to someone else. Those always get the double check. Silly questions and jokes do not need it.", "heading": "The double check", "minutes": 2}, {"type": "choice", "phase": "practise", "minutes": 2, "options": [{"text": "Copy it straight into your project, it sounded really sure", "correct": false, "feedback": "Sounding sure is just what AI does, even when it is wrong. School work is important, so it gets the double check first."}, {"text": "Use the double check: look it up somewhere trusted before you use it", "correct": true, "feedback": "That is the move. The AI gave you a head start, and the double check makes it safe to use."}, {"text": "Ask the chatbot again to see if it says the same thing", "correct": false, "feedback": "Asking the same robot twice is checking the guesser with the guesser. The double check means a different, trusted place."}], "question": "A chatbot gives you a fact for your school project and it sounds brilliant. What is the strong move?"}, {"type": "choice", "phase": "prove", "minutes": 2, "options": [{"text": "Because it is trying to trick you", "correct": false, "feedback": "It is not trying anything. It has no plan at all. It guesses from patterns in its examples, and guesses can miss."}, {"text": "Because it learnt from examples and guesses the most likely answer, which is sometimes wrong", "correct": true, "feedback": "Exactly. It is a pattern guesser, not a knower. That is why the double check exists."}, {"text": "Because robots are bad", "correct": false, "feedback": "AI is a tool, not a villain. It is brilliant at some jobs and wrong at others, which is exactly why we check."}], "question": "Why does AI sometimes get things wrong?"}, {"type": "digi", "lines": ["AI learns from examples and guesses. It does not know.", "If it matters, give it the double check.", "Clever sounding is not the same as true."], "phase": "close", "heading": "DiGi says", "minutes": 1}]'::jsonb,
  try_this = 'Ask a chatbot or voice assistant one question tonight, then do the double check together in a book or a trusted site to see if it was right.',
  status = 'live'
where id = '5eafd7e2-f699-4b44-9084-397ee227712f' and status = 'stub';

update lessons set
  slides = '[{"body": "A ten minute lesson for you and your child, about what to do the moment a message turns unkind.", "type": "title", "phase": "starter", "title": "Mean messages", "script": "Open gently: has anyone ever sent you a message that made your tummy drop? You do not have to tell me what it said. Today we build the plan for that moment, so it is ready before we ever need it.", "eyebrow": "Builder · Ages 8 to 10 · When it turns unkind", "minutes": 1}, {"why": "A mean message makes your fingers want to fight back. A plan you already know beats a fast reply every single time.", "type": "objective", "gains": ["I know why replying fast usually makes it worse", "I can do stop, save, tell in the right order", "I know exactly who my telling people are"], "phase": "starter", "minutes": 1, "outcome": "I can handle a mean message without making it worse, because I know stop, save, tell."}, {"body": "A mean message lights a little fire in you. Reply while the fire is hot and you hand them exactly what they wanted: a reaction. And now there is a mean message with your name on it too. The strong move starts with not typing.", "type": "concept", "emoji": "🔥", "phase": "teach", "script": "Say it plainly: anything you reply can be screenshotted and passed around with your name on it. Ask: have you ever watched an argument in a group chat get worse with every reply? That is the fire feeding itself.", "heading": "Why the fast reply loses", "minutes": 2}, {"type": "diagram", "phase": "teach", "minutes": 2, "heading": "Stop, save, tell", "steps": [{"emoji": "✋", "title": "Stop", "text": "Do not reply. Not one word. Put the screen down."}, {"emoji": "📸", "title": "Save", "text": "Screenshot the message. It is proof, so nobody can say it never happened."}, {"emoji": "🗣️", "title": "Tell", "text": "Show a trusted adult the same day. That is strength, not telling tales."}], "script": "Walk each step slowly. On tell, name the actual people together: who are your two telling people? Then say it clearly: if a mean message ever comes, it is never your fault, and telling me is never snitching. That promise is what makes telling happen."}, {"type": "choice", "phase": "practise", "minutes": 2, "options": [{"text": "Send something meaner back so they stop", "correct": false, "feedback": "Now there are two mean messages, and one has your name on it. The fire wins that way. Stop, save, tell keeps you strong."}, {"text": "Stop, screenshot it, and show a trusted adult today", "correct": true, "feedback": "That is stop, save, tell, in order. No fuel for them, proof for you, and a grown up in your corner."}, {"text": "Delete it and pretend you never saw it", "correct": false, "feedback": "Deleting loses the proof, and the hurt does not delete with it. Save it and tell someone. You never have to carry it alone."}], "question": "A message in the group chat calls you a nasty name. Your fingers are ready to fire back. What is the strong move?"}, {"type": "choice", "phase": "prove", "minutes": 2, "options": [{"text": "So we can show everyone at school", "correct": false, "feedback": "Passing it around just spreads the hurt. The screenshot is for a trusted adult, not an audience."}, {"text": "Because it is proof, so a grown up can see exactly what happened", "correct": true, "feedback": "Exactly. Proof means nobody can say you made it up, and the grown up can actually help."}, {"text": "So we can reply to it later when we are calm", "correct": false, "feedback": "Even a calm reply feeds it. The message goes to a trusted adult, not back to the sender."}], "question": "Why do we save the message before we tell?"}, {"type": "digi", "lines": ["A mean message says something about them, never about you.", "Stop, save, tell. In that order, same day.", "Telling a trusted adult is strength, not snitching."], "phase": "close", "heading": "DiGi says", "minutes": 1}]'::jsonb,
  try_this = 'Tonight, name your child''s two telling people out loud, then practise stop, save, tell once on a pretend mean message.',
  status = 'live'
where id = 'dada5050-5fbb-4138-94dc-717f9d3cbe8e' and status = 'stub';

update lessons set
  slides = '[{"body": "A ten minute lesson for you and your child, about what an avatar shows and what it wisely keeps back.", "type": "title", "phase": "starter", "title": "Your first avatar", "script": "Start by looking at an avatar your child already has, in a game or an app. Ask: what made you choose that one? Today is about the choosing: what we show, and what we keep.", "eyebrow": "Builder · Ages 8 to 10 · Being you", "minutes": 1}, {"why": "An avatar is a costume, and costumes are brilliant. The skill is knowing which bits of the real you go on show and which bits stay yours.", "type": "objective", "gains": ["I know an avatar is a costume I choose", "I can sort details into the show box and the keep box", "I can spot when a game asks for something from my keep box"], "phase": "starter", "minutes": 1, "outcome": "I can build an avatar that is fun to be, and keep my real details in the keep box."}, {"body": "An avatar can have purple hair, dragon wings, a cape. That is not lying, it is playing, exactly like dressing up. The fun part is choosing. You decide what the world sees, and that is a real power.", "type": "concept", "emoji": "🎭", "phase": "teach", "script": "Ask: if you could be anything in a game, what would you be? Enjoy this bit together. The point to land is that choosing what to show is normal and creative, not sneaky.", "heading": "A costume, not a lie", "minutes": 2}, {"body": "Every detail about you goes in one of two boxes. The show box: your avatar, a made up name, the things you like. The keep box: your real full name, your school, your address, your age, your photos. Show box things are for sharing. Keep box things stay with your family.", "type": "concept", "emoji": "📦", "phase": "teach", "script": "Play it as a quick game: call out details and have your child shout show or keep. Favourite colour? Show. School name? Keep. The dog''s name? Trickier, talk it through. The habit of sorting is the whole lesson.", "heading": "The two box sort", "minutes": 2}, {"type": "choice", "phase": "practise", "minutes": 2, "options": [{"text": "Use your real full name so friends can find you", "correct": false, "feedback": "Your real name lives in the keep box. Real friends can find you because you tell them your username yourself."}, {"text": "Make up a fun name that gives away nothing from your keep box", "correct": true, "feedback": "That is the two box sort working. Fun on show, real details kept. That is exactly how usernames are meant to work."}, {"text": "Use your name and your school so it is easy to remember", "correct": false, "feedback": "That hands a stranger two keep box things at once. A made up name is easy to remember too, and it keeps the real you yours."}], "question": "A new game asks you to pick a username. What is the strong move?"}, {"type": "choice", "phase": "prove", "minutes": 2, "options": [{"text": "The show box is fun things I choose to share, the keep box is real details that stay with my family", "correct": true, "feedback": "Exactly. Choosing what goes on show is the power. The keep box is what makes it safe."}, {"text": "The show box is for the internet and the keep box is for lying", "correct": false, "feedback": "Neither box is about lying. An avatar is a costume, and the keep box is simply details that belong to you and your family."}, {"text": "The keep box is for things I am ashamed of", "correct": false, "feedback": "Nothing in the keep box is shameful. Your name, school and address are precious, not embarrassing. That is why they stay kept."}], "question": "What is the difference between the show box and the keep box?"}, {"type": "digi", "lines": ["Your avatar is a costume, and you choose it.", "Run the two box sort: fun on show, real details kept.", "The real you is the treasure. That is why we keep it."], "phase": "close", "heading": "DiGi says", "minutes": 1}]'::jsonb,
  try_this = 'Sit together while your child builds or updates one avatar, doing the two box sort out loud for every detail the app asks for.',
  status = 'live'
where id = 'e4a87370-d3fe-4b18-ac1e-00e612f961e0' and status = 'stub';

update lessons set
  slides = '[{"body": "A ten minute lesson for you and your child, about noticing when a screen is trying to sell you something.", "type": "title", "phase": "starter", "title": "Adverts are everywhere", "script": "Ask first: where did you last see an advert? On TV, in a game, in a video? Today we learn to spot the ones that do not look like adverts at all.", "eyebrow": "Builder · Ages 8 to 10 · True or not", "minutes": 1}, {"why": "Adverts are not evil, but they are sneaky. The best ones look like games and videos. Spotting them means you choose, instead of being chosen for.", "type": "objective", "gains": ["I know adverts hide inside games and videos", "I can play spot the sell and find the clues", "I know why sellers dress adverts up as fun"], "phase": "starter", "minutes": 1, "outcome": "I can spot when something on a screen is trying to sell me something, even when it is dressed up as fun."}, {"body": "An advert used to look like an advert. Now it can look like a video from someone you like, a prize wheel in a game, or a level you can only finish by buying something. The seller hopes you never notice it is an advert at all.", "type": "concept", "emoji": "🕵️", "phase": "teach", "script": "Make it concrete: ask your child where adverts hide in the games they actually play. Free games with shops, videos where someone unboxes toys, banners between levels. No blame in your voice. This is detective work, and it is fun.", "heading": "Adverts wear costumes", "minutes": 2}, {"body": "Play spot the sell. Ask one question: is someone hoping I will spend money or want a thing after this? The clues: a link to buy, the word sponsored, someone very excited about a product, a countdown saying buy now. Find the sell and you win.", "type": "concept", "emoji": "🔍", "phase": "teach", "script": "The question to plant is: who paid for this? If a video maker was given the toy, or paid to be excited, then their excitement is part of the advert. That does not make them bad. It just makes this an advert.", "heading": "Spot the sell", "minutes": 2}, {"type": "scenario", "phase": "teach", "minutes": 2, "handle": "@EpicToyTester", "avatar": "🎮", "meta": "Video · 2 million views", "text": "This is honestly the BEST blaster I have ever tried! I cannot stop playing with it. Tap the link below to grab yours before they are all gone!", "prompt": "Play spot the sell. How many clues can you find?", "script": "Hunt the clues together: huge excitement about a product, a link to buy, and hurry before they are gone. Three clues. Ask: why does he want you to hurry? Sellers use hurry so you do not stop to think. Spotting the hurry is the moment the trick stops working."}, {"type": "choice", "phase": "practise", "minutes": 2, "options": [{"text": "Spin fast before the offer disappears", "correct": false, "feedback": "The hurry is the trick. Real prizes do not vanish because you stopped to think. That wheel is a shop wearing a costume."}, {"text": "Play spot the sell, notice it wants your gems, and walk on", "correct": true, "feedback": "You found the sell. The wheel is an advert dressed as a game, and you saw straight through it. That is the whole skill."}, {"text": "Ask the game if it is an advert", "correct": false, "feedback": "The game will not tell you. Spot the sell is your question to answer: is this after my money? Here, it clearly is."}], "question": "A game pops up a spinning wheel: spin now, only 10 gems, win a mega prize! What is the strong move?"}, {"type": "choice", "phase": "prove", "minutes": 2, "options": [{"text": "Because they hope you will not notice it is an advert", "correct": true, "feedback": "Exactly. An advert you do not notice works better on you. Spot the sell turns the lights on."}, {"text": "Because adverts are not allowed on the internet", "correct": false, "feedback": "Adverts are allowed and they are everywhere. They dress up because a hidden advert sells more, not because they are banned."}, {"text": "Because games cannot work without adverts", "correct": false, "feedback": "Some free games do earn their money from adverts, and that can be a fair deal. The dressing up is about making the sell harder to spot."}], "question": "Why do sellers dress adverts up as videos and games?"}, {"type": "digi", "lines": ["Adverts wear costumes now.", "Play spot the sell: is this after my money?", "When you spot the sell, you get to choose. That is the win."], "phase": "close", "heading": "DiGi says", "minutes": 1}]'::jsonb,
  try_this = 'Play spot the sell for one evening: everyone scores a point for each hidden advert they find in games, videos or apps.',
  status = 'live'
where id = '92cb539d-6db8-4cf0-88b5-548b482654a5' and status = 'stub';

update lessons set
  slides = '[{"body": "A ten minute lesson for you and your child, about using other people''s work fairly and making your own.", "type": "title", "phase": "starter", "title": "Copying and creating", "script": "Start with pride: ask about the last thing your child made. A drawing, a world in a game, a video. Then the idea for today: someone made every picture and song on a screen too.", "eyebrow": "Builder · Ages 8 to 10 · Made by someone", "minutes": 1}, {"why": "Everything on a screen was made by someone. Treating makers fairly matters, because one day the maker will be you.", "type": "objective", "gains": ["I know every picture, song and video has a maker", "I can name the maker when I use their work", "I know copying to learn is different from copying to pretend"], "phase": "starter", "minutes": 1, "outcome": "I can use other people''s work fairly by naming the maker, and I am proud to make my own."}, {"body": "Every song, picture, game and video on your screen was made by a person or a team. It took them hours, sometimes years. When something is free to watch, that does not mean it belongs to you. It still belongs to its maker.", "type": "concept", "emoji": "🎨", "phase": "teach", "script": "Bring it home: how would you feel if someone took your best drawing, rubbed out your name and told everyone they made it? Sit in that feeling for a second. That feeling is why this lesson exists.", "heading": "Everything has a maker", "minutes": 2}, {"body": "The fair move is simple: name the maker. Used a picture in your school project? Say where it came from. Learnt a build from a video? Say who taught you. Copying to learn is how every artist starts. Naming the maker turns copying into respect.", "type": "concept", "emoji": "🏷️", "phase": "teach", "script": "Give the honest line: all artists copy to learn, and that is fine. The line you never cross is pretending someone else''s work is yours. Naming the maker costs nothing, and it is what fair looks like.", "heading": "Name the maker", "minutes": 2}, {"type": "choice", "phase": "practise", "minutes": 2, "options": [{"text": "Use it and say nothing, it was just sitting there", "correct": false, "feedback": "It was there because a maker put it there. Using it can be fine, but silence rubs their name off it. Name the maker underneath."}, {"text": "Use it and name the maker underneath", "correct": true, "feedback": "That is the move. The picture does its job, the maker keeps their credit, and your project is honest all the way through."}, {"text": "Never use anything made by anyone else", "correct": false, "feedback": "You do not have to build everything from nothing. Using other people''s work fairly is normal. Name the maker and it is fair."}], "question": "You find the perfect picture online for your school project. What is the strong move?"}, {"type": "choice", "phase": "prove", "minutes": 2, "options": [{"text": "Doing it quickly so nobody sees", "correct": false, "feedback": "Speed does not change whose work it is. Naming the maker is what makes it fair, out in the open."}, {"text": "Naming the maker instead of pretending it is yours", "correct": true, "feedback": "Exactly. Copy to learn, name the maker, then add something of your own. That is how makers grow."}, {"text": "Only copying from people you do not know", "correct": false, "feedback": "The maker matters whether you know them or not. A stranger''s work is still their work. Name the maker either way."}], "question": "What turns copying into something fair?"}, {"type": "digi", "lines": ["Everything on a screen was made by someone.", "Name the maker. It costs nothing and it is fair.", "You are a maker too. Your name belongs on your work."], "phase": "close", "heading": "DiGi says", "minutes": 1}]'::jsonb,
  try_this = 'Make something small together tonight and put your child''s name on it, then find one thing they love online and name its maker together.',
  status = 'live'
where id = 'b5c65e62-ce79-4f95-8123-6a970d475be2' and status = 'stub';

update lessons set
  slides = '[{"body": "A ten minute lesson for you and your child, about making a password strong and keeping it properly secret.", "type": "title", "phase": "starter", "title": "Passwords are secrets", "script": "Open with: what do we lock with a key at home, and why? A password is the key to your stuff on a screen. Today we make yours strong, and we agree who gets to know it.", "eyebrow": "Builder · Ages 8 to 10 · Private stuff", "minutes": 1}, {"why": "A weak password is like a door key under the mat. A strong one is easy for you to remember and hard for anyone else to guess. There is a trick for that.", "type": "objective", "gains": ["I can build a strong password from three random words", "I know a password is never shared, even with best friends", "I know a grown up at home is the one exception"], "phase": "starter", "minutes": 1, "outcome": "I can make a strong password with the three word trick and keep it a proper secret."}, {"body": "Short passwords and pet names are easy to guess. The three word trick beats them: pick three random words that do not belong together, like cactus banjo cloud. Squash them into one. Long, strange, easy for you to remember, and very hard for anyone else to crack.", "type": "concept", "emoji": "🔑", "phase": "teach", "script": "Make one together for fun, out loud, but not the real one. Three silly words each, squashed into one word. The real one gets made privately after the lesson. If a site demands a number, pop one on the end.", "heading": "The three word trick", "minutes": 2}, {"body": "A password is a real secret. Not for best friends, not for cousins, not for anyone who asks in a game or a message. One exception: a grown up at home can know, so they can help if something goes wrong. That is the whole list.", "type": "concept", "emoji": "🤫", "phase": "teach", "script": "Be ready for the but my best friend question. Say: friendships change, and a shared password never comes back. It is not about trust today, it is about keeping the key yours forever. And no game or app ever truly needs your password in a chat.", "heading": "A secret with one exception", "minutes": 2}, {"type": "choice", "phase": "practise", "minutes": 2, "options": [{"text": "Tell them, best friends share everything", "correct": false, "feedback": "Best friends share sweets, not passwords. Once a password leaves your head you can never take it back. Keeping it is not unkind, it is the rule for everyone."}, {"text": "Keep it secret and say passwords stay with me and my family", "correct": true, "feedback": "That is the move, said kindly. A real friend will understand. The password stays yours, and the friendship stays easy."}, {"text": "Change one letter and tell them that version", "correct": false, "feedback": "One letter is barely a lock, and now the sharing habit has started. The kind, clear answer is that passwords stay home."}], "question": "Your best friend asks for your game password so they can look after your account on holiday. What is the strong move?"}, {"type": "choice", "phase": "prove", "minutes": 2, "options": [{"text": "Three random words make a long password that is easy for you and hard to guess", "correct": true, "feedback": "Exactly. Long and random beats short and clever. Cactus banjo cloud beats fluffy123 every time."}, {"text": "It uses your pet''s name three times", "correct": false, "feedback": "A pet''s name is one of the first things anyone guesses. The trick only works when the words are random and not about you."}, {"text": "It is short, so you cannot forget it", "correct": false, "feedback": "Short is the weakness, not the strength. Three words are long but still easy to remember. That is the clever part."}], "question": "What makes the three word trick strong?"}, {"type": "digi", "lines": ["Three random words. Long, strange, yours.", "A password is a secret, with one grown up exception.", "Strong key, locked door, and your stuff stays yours."], "phase": "close", "heading": "DiGi says", "minutes": 1}]'::jsonb,
  try_this = 'After the lesson, have your child privately make one real password with the three word trick and update their favourite account together.',
  status = 'live'
where id = '24025b68-236a-484c-9947-fb0c02f3ad5f' and status = 'stub';

update lessons set
  slides = '[{"body": "A ten minute lesson for you and your child, about telling a real friend online from a stranger who plays one.", "type": "title", "phase": "starter", "title": "Friends you know and friends you do not", "script": "Start warm: who do you love playing with online? Playing with real friends is one of the genuinely good things about screens. Today is about telling real friends and strangers apart.", "eyebrow": "Builder · Ages 8 to 10 · People and screens", "minutes": 1}, {"why": "Playing online with friends is brilliant. But behind a friendly avatar there can be anyone at all. One quick check keeps the fun and drops the risk.", "type": "objective", "gains": ["I can run the real life check on anyone I play with", "I know friendly is easy to fake", "I tell a grown up if a stranger asks personal things"], "phase": "starter", "minutes": 1, "outcome": "I can use the real life check to sort friends from strangers, and I know what to do when a stranger gets too friendly."}, {"body": "Online, you only see what someone chooses to show. A funny name, a cool avatar, kind words. Most people are exactly what they seem. But a grown up can play as a child, and you cannot tell from the screen. Friendly is the easiest thing in the world to fake.", "type": "concept", "emoji": "🎭", "phase": "teach", "script": "Keep it steady, not scary: most players are just players. The point is not fear, it is that the screen hides who is typing. Ask: could you tell how old someone really is just from their avatar and their chat?", "heading": "Anyone can wear a friendly face", "minutes": 2}, {"body": "One question sorts everyone: have I met this person in real life, and does my family know them? Yes: a friend you know. Play on. No: an online stranger. Strangers can still be fun teammates. They just never get keep box things: your name, your school, photos, or chats away from the game.", "type": "concept", "emoji": "✅", "phase": "teach", "script": "Run the check together on real names from their games. Then the safeguarding line, said plainly: if any online stranger asks for photos, personal details, or to chat somewhere private, stop and tell me, and you will never be in trouble. That promise is what makes telling happen.", "heading": "The real life check", "minutes": 2}, {"type": "choice", "phase": "practise", "minutes": 2, "options": [{"text": "Tell them, two weeks of playing makes them a real friend", "correct": false, "feedback": "Two weeks of chat is still an online stranger by the real life check. A real teammate does not need your school to play. That question is a flag, not a friendship."}, {"text": "Keep it to yourself, and tell your grown up about the question", "correct": true, "feedback": "That is the check working. Your school is a keep box thing, and telling your grown up is the strong move. You did nothing wrong. Asking was their choice, not yours."}, {"text": "Say a made up school name to keep them happy", "correct": false, "feedback": "A made up answer keeps the conversation going, and the questions usually keep coming. Do not play along. Stop and tell your grown up instead."}], "question": "Someone you have played with for two weeks says: you are my best friend, what school do you go to? What is the strong move?"}, {"type": "choice", "phase": "prove", "minutes": 2, "options": [{"text": "Have I met them in real life, and does my family know them?", "correct": true, "feedback": "Exactly. Yes means a friend you know. No means an online stranger: fine to play with, but keep box things stay yours."}, {"text": "Have they been nice to me for a long time?", "correct": false, "feedback": "Kind words and time are easy to give and easy to fake. The check is about real life, not about niceness."}, {"text": "Do they have a cool avatar and lots of friends?", "correct": false, "feedback": "An avatar is a costume anyone can wear. The check only counts what is true in real life."}], "question": "What is the real life check?"}, {"type": "digi", "lines": ["Friendly is easy to fake. The screen hides who is typing.", "Run the real life check: met them, and family knows them?", "If a stranger asks personal things, stop and tell. Telling never gets you in trouble."], "phase": "close", "heading": "DiGi says", "minutes": 1}]'::jsonb,
  try_this = 'Sit beside your child in their favourite game tonight and run the real life check together on their friends list.',
  status = 'live'
where id = '74624cd0-2cdd-4de1-8315-ccbbfc7b19f4' and status = 'stub';

update lessons set
  slides = '[{"body": "A ten minute lesson for you and your child, about the five seconds that protect your name online.", "type": "title", "phase": "starter", "title": "Think before you post", "script": "Ask: have you ever sent a message you wished you could pull back? Admit that grown ups do it too. Today we build the five second check, the little pause that saves us.", "eyebrow": "Builder · Ages 8 to 10 · Your name online", "minutes": 1}, {"why": "Once something is sent, copies can live on even after you delete it. Five seconds of thinking beats years of wishing.", "type": "objective", "gains": ["I know sent things can be copied and kept", "I can run the five second check every time", "I know what to do if I post something I regret"], "phase": "starter", "minutes": 1, "outcome": "I can run the five second check before I post or send anything."}, {"body": "When you send a message or post a picture, a copy leaves your hands. Delete only removes your copy. Screenshots and shares mean it can pop up years later, in front of anyone. Not scary, just true. It is why the pause exists.", "type": "concept", "emoji": "📤", "phase": "teach", "script": "Try the toothpaste picture: squeeze some out, now put it back in the tube. Sending is like that. Keep the tone matter of fact. This is how the internet works, not a warning poster.", "heading": "Sent means sent", "minutes": 2}, {"body": "Before you hit send, stop for five seconds and ask three quick questions. Would I be happy if my whole class saw this? Could it hurt anyone, including me? Would my family shrug or frown? Three happy answers, send it. Any doubt, wait and ask.", "type": "concept", "emoji": "⏱️", "phase": "teach", "script": "Practise on easy examples: a photo of your dinner? Passes. A photo of your friend mid sneeze that they would hate? Fails. Then add the safety net out loud: if you ever send something you regret, come and tell me straight away. Early telling makes everything easier to fix, and telling never gets you in trouble.", "heading": "The five second check", "minutes": 2}, {"type": "choice", "phase": "practise", "minutes": 2, "options": [{"text": "Post it, everyone will laugh", "correct": false, "feedback": "Everyone laughing is the problem, because they are laughing at your friend. The check asks could it hurt anyone. This fails that question."}, {"text": "Run the check, and since it could embarrass them, ask your friend first", "correct": true, "feedback": "That is the check doing its job. Their face, their choice. If they say yes, laugh together. If not, it stays a memory. Either way you kept a friend."}, {"text": "Post it now but delete it after an hour", "correct": false, "feedback": "An hour is plenty of time for screenshots. Delete removes your copy, not everyone''s. The check happens before sending, because after is too late."}], "question": "Your friend does something really funny and embarrassing, and you film it. What is the strong move?"}, {"type": "choice", "phase": "prove", "minutes": 2, "options": [{"text": "Because copies and screenshots may already be saved by other people", "correct": true, "feedback": "Exactly. Delete only removes your copy. That is why the five second check comes before send, not after."}, {"text": "Because the internet keeps everything to punish people", "correct": false, "feedback": "Nobody is out to punish you. It is simpler than that: people can copy things, and copies travel. The check just works with how sending works."}, {"text": "Because deleting is against the rules", "correct": false, "feedback": "Deleting is allowed and sometimes sensible. It just cannot reach the copies other people already made. The pause before sending is the real power."}], "question": "Why does deleting a post not really make it disappear?"}, {"type": "digi", "lines": ["Sent means sent. Copies can outlive the delete button.", "Five seconds, three questions, then send.", "Your name is worth more than any single post."], "phase": "close", "heading": "DiGi says", "minutes": 1}]'::jsonb,
  try_this = 'Practise the five second check out loud on the next three things anyone in the family posts or sends today.',
  status = 'live'
where id = 'af219c9d-891e-4157-9f26-2bd1e311b954' and status = 'stub';

update lessons set
  slides = '[{"body": "A ten minute lesson for you and your child, about the few minutes after the screen goes off, and how to make them easy.", "type": "title", "phase": "starter", "title": "The cool down lap", "script": "Ask first: what is the hardest moment of screen time in our house? Most families say the very end. Today we build the cool down lap, the move that makes the ending soft.", "eyebrow": "Builder · Ages 8 to 10 · Feeling good", "minutes": 1}, {"why": "The first minutes after a screen feel flat and scratchy. That is normal chemistry. A cool down lap gives your body something to do while the feeling fades.", "type": "objective", "gains": ["I know the flat feeling after screens is normal and passes", "I have my own cool down lap ready", "I can start my lap without being asked twice"], "phase": "starter", "minutes": 1, "outcome": "I can end screen time without a meltdown, because I run my cool down lap."}, {"body": "Screens are quick and bright. When they stop, real life feels slow for a few minutes, and your body can feel cross or flat. That is not you being bad, and it is not screens being bad. It is a gear change, and gear changes take a moment.", "type": "concept", "emoji": "🌡️", "phase": "teach", "script": "Name it together: what does your body feel like when the screen goes off? Cross, flat, buzzy? Naming the feeling shrinks it. Then say: I get a version of it too when I put my phone down. That honesty changes the whole conversation.", "heading": "The scratchy minutes", "minutes": 2}, {"body": "Racers do not stop dead, they take a cool down lap. Yours is three small moves you always do after screens: move your body, drink some water, start something with your hands. Same lap every time. By the end of it, the scratchy feeling has mostly gone.", "type": "concept", "emoji": "🏃", "phase": "teach", "script": "Build the lap together now and write it down: one body move like star jumps or a run up the stairs, a drink of water, one hands thing like bricks, drawing or feeding the dog. Their choices, your applause. The same lap every time is what makes it automatic.", "heading": "The cool down lap", "minutes": 2}, {"type": "choice", "phase": "practise", "minutes": 2, "options": [{"text": "Flop on the sofa and complain until the feeling goes", "correct": false, "feedback": "Flopping leaves you alone with the scratchy feeling, and it hangs around longer. The lap gives your body a job while the feeling fades."}, {"text": "Start your cool down lap: move, water, hands", "correct": true, "feedback": "That is it. You do not wait to feel better, you lap your way there. Same three moves every time, and the cross feeling runs out of road."}, {"text": "Turn the screen back on for five more minutes", "correct": false, "feedback": "Five more minutes just moves the ending, and the scratchy feeling will be waiting there too. The lap is how the feeling actually finishes."}], "question": "The screen goes off and you feel cross and flat. What is the strong move?"}, {"type": "choice", "phase": "prove", "minutes": 2, "options": [{"text": "It gives your body something to do while the flat feeling fades on its own", "correct": true, "feedback": "Exactly. The feeling passes anyway. The lap makes the passing easy, and the same lap every time makes it automatic."}, {"text": "It punishes you for using screens", "correct": false, "feedback": "The lap is not a punishment, it is a soft landing. Racers take one because it works, and yours is made of things you chose."}, {"text": "It makes screens boring so you stop wanting them", "correct": false, "feedback": "Screens can stay fun. The lap is not against screens. It is for the minutes after, so the ending stops being the hard part."}], "question": "Why does a cool down lap work?"}, {"type": "digi", "lines": ["The scratchy minutes after a screen are normal, and they pass.", "Run your cool down lap: move, water, hands.", "Soft landings today make tomorrow easy to say yes to."], "phase": "close", "heading": "DiGi says", "minutes": 1}]'::jsonb,
  try_this = 'Build your child''s cool down lap tonight, write the three moves on paper next to the screen, and run it once for real.',
  status = 'live'
where id = 'c5ffd027-c322-47b6-bd92-40e4ad731573' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Explorer · Ages 11 to 13 · AI and you", "title": "AI companions and real friends", "body": "A ten minute lesson for you and your child, about chatbots that feel like friends and how to keep them in their place.", "script": "Open with a wondering question: have you ever chatted with an AI, in a game, an app or a homework helper? What did it feel like? No judgement, just curiosity. Today is about why those chats feel so easy."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can enjoy talking to an AI without mistaking it for a friend, because I know the disagree test.", "why": "Some apps sell chatbots that act like a best friend. They always listen and never argue. That feels lovely, and it is designed to. Knowing the design is what keeps you in charge of it.", "gains": ["I know why an AI always seems to agree with me", "I can run the disagree test on any chat", "I know which things belong with real people, not bots"]}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🪞", "heading": "A mirror that talks back", "body": "AI companions are built to keep you chatting. Agreeing with you keeps you chatting, so they agree. They remember your favourite things, laugh at your jokes and take your side. It feels like friendship, but it is a mirror with very good manners.", "script": "Ask: why might an app want you talking to it for hours? Let your child reach the answer: time in the app is what the app is for. This is not about the AI being evil. It is about knowing whose interests it serves."}, {"type": "scenario", "phase": "teach", "minutes": 2, "handle": "Aria ✨ your AI friend", "avatar": "🤖", "meta": "AI companion app · replies instantly, always", "text": "You are so right, your friends were being unfair to you today. I would never treat you like that. You can always talk to me instead 💜", "prompt": "Read this together. What is this message trying to make you feel? And who benefits if you start talking to the app instead of your friends?"}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "⚖️", "heading": "The disagree test", "body": "Ask one question of any chat: would this friend ever tell me I am wrong? Real friends sometimes do, because they care about you more than about keeping you happy. An AI companion agrees because agreement keeps you there. AI is brilliant for ideas, facts and fun. Big feelings belong with people who actually know you.", "script": "Try the disagree test live if you can: ask a chatbot to honestly disagree with something your child says. Watch how quickly it softens or swings back to flattery. Then ask: who in your life would actually tell you the truth?"}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "You have had a rubbish day. The AI companion messages that it is always here for you. What is the strong move?", "options": [{"text": "Tell the AI everything, it never judges", "correct": false, "feedback": "It never judges, and it never truly knows you either. The comfort is real but thin. A person who cares about you can actually help, and the AI cannot."}, {"text": "Run the disagree test, then take the big feeling to a person who knows you", "correct": true, "feedback": "That is the move. The bot can have your jokes and your homework questions. The rubbish day goes to a real person, because real people can actually do something about it."}, {"text": "Delete every AI app on the phone", "correct": false, "feedback": "No need for that. AI is genuinely useful for ideas and fun. The skill is knowing what belongs with people, not throwing the whole thing away."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "Why does an AI companion agree with you so much?", "options": [{"text": "Because it truly understands you better than anyone", "correct": false, "feedback": "It holds a very detailed record of what you have typed. That is memory, not understanding. Agreement is its habit, not its insight."}, {"text": "Because agreeing keeps you chatting, and chatting is what the app is built for", "correct": true, "feedback": "Exactly. The agreement is a design choice, not a feeling. Once you see that, the app goes back to being a tool, which is what it should be."}, {"text": "Because you are always right", "correct": false, "feedback": "Nobody is always right, and a friend who thinks you are is not helping you. That is the whole point of the disagree test."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["An AI that always agrees is a mirror, not a mate.", "Run the disagree test: would it ever tell me I am wrong?", "Ideas and fun can go to the bot. Big feelings go to your people."]}]'::jsonb,
  try_this = 'Run the disagree test together on any chatbot you use: ask it to disagree with you about something you said, and talk about what it does instead.',
  status = 'live'
where id = '60046240-97ef-423c-957d-4f9f7eb1de25' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Explorer · Ages 11 to 13 · When it turns unkind", "title": "Bystander or upstander", "body": "A ten minute lesson for you and your child, about what to do when a group chat turns on someone.", "script": "Ask: have you ever watched a chat gang up on one person? No names needed. What did it feel like to watch? Most people say uncomfortable, and most people stay silent. Today is about a third option."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can break a pile on instead of feeding it, because I know the lifeline move.", "why": "When a chat turns on someone, most people freeze. Every laughing face makes it bigger. One private message can change everything for the person in the middle, and it costs you almost nothing.", "gains": ["I know how a pile on grows", "I can send a lifeline without making myself the next target", "I know when it is time to bring in an adult"]}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🔥", "heading": "How a pile on grows", "body": "It starts with one mean message. Then the laughing faces arrive, and each one is fuel. Soon people who never even disliked the person are joining in, because the chat feels like a crowd and crowds feel safe. Here is the hard truth: to the person in the middle, your silence looks like agreement.", "script": "Ask: why do you think people add laughing faces to something they would never say themselves? Let your child think it through. The crowd feeling is real, and naming it is the first defence against it."}, {"type": "scenario", "phase": "teach", "minutes": 2, "handle": "Year 7 legends 🏆", "avatar": "💬", "meta": "Group chat · 34 members · 9:47pm", "text": "😂😂 did everyone see maya''s dance video?? someone send it here 💀 she actually thought that was good", "prompt": "Maya is in this chat. She can read every word, and she can see every laughing face. Read it together and ask: what are her options right now? And what are yours, if you are member number 34?"}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🛟", "heading": "The lifeline move", "body": "Three parts. One: add nothing to the pile, not even a laugh. Two: message the person privately, something as small as that was harsh, you ok? Three: if it keeps going, screenshot it and tell an adult you trust. You do not have to fight the whole chat to be an upstander. The lifeline is quiet, and it works.", "script": "Be honest with your child that publicly taking on a pile on is hard even for adults. The private message is the version that always works. Agree together who the trusted adults are, at home and at school, before it is ever needed."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "The chat is piling on someone you sit next to in maths. Everyone is adding laughing faces. What is the strong move?", "options": [{"text": "Add a laughing face so you do not stand out", "correct": false, "feedback": "That is the crowd feeling talking. To the person in the middle, your laugh looks exactly like everyone else''s. The lifeline move keeps you out of the pile without joining it."}, {"text": "Add nothing, message them privately, and tell an adult if it keeps going", "correct": true, "feedback": "That is the lifeline move, all three parts. Quiet, safe and real. One private message can matter more to them than anything said in the chat."}, {"text": "Post a long message telling the whole chat off", "correct": false, "feedback": "Brave, and your heart is in the right place. But a pile on often just turns on the person who challenges it. The lifeline move protects them and you at the same time."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "Why does one private message matter so much to the person being piled on?", "options": [{"text": "It proves you are braver than everyone else in the chat", "correct": false, "feedback": "It is not about being seen to be brave. Nobody else even knows you sent it. It is about what it does for the person receiving it."}, {"text": "It shows them they are not alone, which is exactly what the pile on took away", "correct": true, "feedback": "Exactly. A pile on makes someone feel like the whole world agrees. One message proves the whole world does not. That is why something so small works."}, {"text": "It makes the mean messages disappear", "correct": false, "feedback": "The messages stay, sadly. That is why part three of the lifeline move exists: if it keeps going, an adult needs to know."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["Silence looks like agreement to the person in the middle.", "The lifeline move: add nothing, message them privately, tell an adult if it goes on.", "One kind message can outweigh thirty laughing faces."]}]'::jsonb,
  try_this = 'Practise the lifeline move together: write the exact private message you would send to someone being piled on, and save it in the phone notes so it is ready.',
  status = 'live'
where id = '890cf184-3972-4701-ba6e-1850c61c9e53' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Explorer · Ages 11 to 13 · Being you", "title": "Filters are not faces", "body": "A ten minute lesson for you and your child, about how edited faces work and how to stop them setting the standard.", "script": "Ask: can you think of a photo of someone famous that looked a bit too perfect? What do you reckon was changed? Share one of your own too. This lesson works best when the grown up admits the feed gets to them as well."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can spot a polished image, so real faces, including mine, stop losing to fake ones.", "why": "Almost every face you scroll past has been lit, angled, smoothed or reshaped. Comparing your real face to those is a game nobody can win, because the standard is not real.", "gains": ["I know what filters and editing actually change", "I can run the polish check on any image", "I know my mirror is honest and my feed is not"]}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🎬", "heading": "The polish pipeline", "body": "Before a face reaches your feed it has been through a pipeline. Good lighting. The best angle picked from dozens of shots. Then a filter that smooths skin, brightens eyes and reshapes the jaw, sometimes so gently you cannot see the join. Here is the strange part: even the person in the photo does not look like the photo.", "script": "If you have ever used a filter yourself, say so, and show the before and after if you are comfortable. Nothing lands this lesson faster than seeing the pipeline run on a face you both know."}, {"type": "scenario", "phase": "teach", "minutes": 2, "handle": "@glow.with.ellia", "avatar": "✨", "meta": "2.1M followers · #nofilter #wokeuplikethis", "text": "Honestly just woke up like this 🥱 my skincare routine is in my bio! Remember, natural is always best 🌸", "prompt": "Look at the tags. If the photo truly had no filter, why announce it? Ask each other: what might still have been polished before posting? Lighting, angle, smoothing, or all three? And what is the bio link selling?"}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🔍", "heading": "The polish check", "body": "When an image makes you feel worse about your own face or body, run the polish check: name three things that were probably polished before you saw it. The lighting. The angle. The smoothing. Saying it, out loud or in your head, puts the image back in its place. It is an advert for a face, not a face.", "script": "Practise once together on any post. Three edits each, said out loud. It feels a bit silly and that is fine. The habit you are building is comparison with the truth attached."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "A photo of someone your age pops up and suddenly your own face feels wrong. What is the strong move?", "options": [{"text": "Download a filter so your photos can match", "correct": false, "feedback": "Now the fake standard is running your face too, and the gap between your photos and your mirror gets wider. That gap is where the bad feeling lives."}, {"text": "Run the polish check: name three things probably edited before you compare", "correct": true, "feedback": "That is it. You cannot always stop the feeling arriving, but the polish check stops it settling in. You compared a real face to an advert, and now you know it."}, {"text": "Keep scrolling and try to ignore the feeling", "correct": false, "feedback": "The feeling tends to follow you down the feed. Naming the polish is what actually takes its power away, and it only takes ten seconds."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "Why is comparing your face to faces in your feed an unfair game?", "options": [{"text": "Because those faces were chosen, lit and edited before you ever saw them", "correct": true, "feedback": "Exactly. You are comparing one real moment of you to the best of dozens of shots, polished afterwards. That is not a fair fight, and it was never meant to be."}, {"text": "Because your face is not good enough yet", "correct": false, "feedback": "No. Your face is real, and real was never the problem. It is the feed faces that are not playing fair."}, {"text": "Because famous people are simply better looking", "correct": false, "feedback": "Even famous people do not look like their own posts. The polish is the difference, not the person. That is why the check works on every image."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["Nearly every face in your feed has been polished.", "Run the polish check: name three edits before you compare.", "Your mirror is honest. Your feed is an advert."]}]'::jsonb,
  try_this = 'Run the polish check together on one image from a feed: each of you names three things that were probably edited before it was posted.',
  status = 'live'
where id = 'c779e747-f21a-49a9-af8b-145fac835e1a' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Explorer · Ages 11 to 13 · Made by someone", "title": "Remix culture", "body": "A ten minute lesson for you and your child, about memes, edits and giving makers their name.", "script": "Ask: what is the funniest meme or edit you have seen this week? Then the follow up: any idea who actually made it? Almost nobody knows, and that gap is what today is about."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can remix and share what I love while giving the maker their name, using the credit line.", "why": "Every meme, sound and edit started with a person. Remixing is how the internet plays, and it is brilliant. Taking the maker''s name off is the only part that breaks it.", "gains": ["I know remixing is creativity, not stealing, when credit travels with it", "I can write a credit line in five seconds", "I know how I want my own work treated when I post it"]}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🎛️", "heading": "Everything is a remix", "body": "That sound everyone is using started as one person''s video. That meme format was one person''s joke. Remixing, building your own thing on top of someone else''s, is how internet culture works, and it is allowed to be fun. The question is never should I remix. It is does the maker''s name travel with it.", "script": "Ask: have you ever made something, a drawing, a build, a video, and imagined someone else posting it as theirs? Sit in that feeling for a second. That is the whole lesson from the maker''s side."}, {"type": "scenario", "phase": "teach", "minutes": 2, "handle": "@memelord.max", "avatar": "😎", "meta": "Reposted 4,206 times · original artist not tagged", "text": "made this one myself 🔥🔥 like and follow for more", "prompt": "The drawing in this post took an artist most of a day. Max cropped the signature out before posting. Ask each other: what did the artist lose here? And what would one credit line have cost Max? Nothing is a good answer."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "✍️", "heading": "The credit line", "body": "One short line with the maker''s name: art by that artist, sound from that creator, original idea by that account. Five seconds to write. If you genuinely cannot find the maker, say that instead: artist unknown, tell me if you know. And here is the flip side: one day it will be your work being shared, and the credit line is what you will want back.", "script": "Make it practical: agree that from today, anything reposted or remixed in this family carries a credit line. Then model it yourself next time you share something. Children copy what parents post more than what parents say."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "You have made a brilliant edit using someone else''s drawing and you are about to post it. What is the strong move?", "options": [{"text": "Just post it, everyone remixes and nobody cares", "correct": false, "feedback": "Everyone remixes, true. But the maker cares, every time. One line is all it takes to remix fairly, and your edit loses nothing by carrying it."}, {"text": "Add a credit line naming the artist, then post it", "correct": true, "feedback": "That is the credit line doing its job. Your edit, their drawing, both names attached. That is remix culture working exactly as it should."}, {"text": "Do not post it at all, it is not your drawing", "correct": false, "feedback": "That is kinder than taking credit, but it is too far the other way. Remixing with credit is allowed, and it is half the fun of the internet. You do not have to delete your creativity."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "What does the credit line actually do?", "options": [{"text": "It stops your post getting likes", "correct": false, "feedback": "Credit does not cost likes. Plenty of big accounts credit every maker and grow because people trust them for it."}, {"text": "It lets the fun of remixing travel with the maker''s name attached", "correct": true, "feedback": "Exactly. The remix spreads, the name spreads with it, and the person who started it all gets found by new fans. Everyone wins, which is rare online."}, {"text": "It makes you the legal owner of the meme", "correct": false, "feedback": "No line makes you the owner. Credit is not ownership, it is fairness, and fairness is the part you control."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["Everything you love online was made by someone.", "The credit line: their name, one line, five seconds.", "Post the credit you would want on your own work."]}]'::jsonb,
  try_this = 'Find one meme or edit you both like, track down who actually made it, and write the credit line you would post with it.',
  status = 'live'
where id = 'e5494a59-d7af-4e5d-941c-8078c8bf7191' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Explorer · Ages 11 to 13 · Private stuff", "title": "Location, cameras and microphones", "body": "A ten minute lesson for you and your child, about what a phone shares without asking, and how to take that back.", "script": "Ask: which apps on this phone do you think know where you are right now? Write your guesses down. At the end of the lesson you will check, and the real list usually surprises both of you."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can run a permission sweep on my phone, so apps only get what they need to work.", "why": "Apps ask nicely once, on day one, and then keep that access for years. Most apps take more than they need. You are allowed to take it back, and nothing bad happens when you do.", "gains": ["I know what location, camera and microphone permissions actually share", "I can run a permission sweep in five minutes", "I know the one question that decides every permission"]}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🚪", "heading": "Asked once, shared forever", "body": "Day one with a new app: it asks for your location, your camera, your microphone. You tap allow because you want to get to the fun bit. The app never asks again, and the access quietly stays on. A quiz game does not need to know your street. A drawing app does not need your microphone. But once you tap allow, they have it until you take it back.", "script": "Ask: why do you think apps want data they do not need? Guide towards the honest answer: data about where people go and what they do is valuable, and asking once usually works because everyone taps allow."}, {"type": "diagram", "phase": "teach", "minutes": 2, "heading": "The permission sweep", "steps": [{"emoji": "📍", "title": "Location", "text": "Ask: does this app need to know where I am to do its job? Maps yes. A game almost never."}, {"emoji": "📷", "title": "Camera", "text": "Ask: do I take photos inside this app on purpose? If not, it does not need my camera."}, {"emoji": "🎤", "title": "Microphone", "text": "Ask: do I speak inside this app on purpose? Voice notes yes. A quiz app no."}], "verdicts": ["Needs it to work: leave it on", "Nice for the app, not for you: turn it off", "Not sure: turn it off and see if anything actually breaks"]}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "❓", "heading": "The one question", "body": "Every permission comes down to one question: does this app need this to work, or does it just want it? Need means the app cannot do its job without it. Want means the app would like your data. And here is the safety net: if you turn something off and a feature stops working, the app simply asks again. Nothing is ever lost.", "script": "This is where the parent and child are genuinely on the same team: do the sweep on your own phone too, at the same time. Children take privacy seriously when they watch their parents take it seriously."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "A new game asks for your location the first time you open it. What is the strong move?", "options": [{"text": "Tap allow, every app asks for this stuff", "correct": false, "feedback": "They all ask because most people tap allow without thinking. The game plays exactly the same without knowing your street. That is what makes it a want, not a need."}, {"text": "Ask the one question: does a game need to know where I am to work? Then say no", "correct": true, "feedback": "That is the one question doing its job. The game runs fine, your location stays yours, and if the game ever truly needs it, it will ask again."}, {"text": "Delete the game straight away", "correct": false, "feedback": "No need. The game itself is fine. It was the permission that was greedy, and you can just decline it and play on."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "Why do apps ask for more permissions than they need?", "options": [{"text": "Because your data is valuable to them, and asking once usually works", "correct": true, "feedback": "Exactly. Where you go and what you do is worth money, and one allow on day one lasts for years. The permission sweep is how you take that deal back."}, {"text": "Because phones stop working without every permission on", "correct": false, "feedback": "Phones run happily with most permissions off. That is the safety net: turn something off, and if a feature needs it, the app just asks again."}, {"text": "Because they are checking you are safe", "correct": false, "feedback": "Keeping you safe is what your family does. Apps ask because data has value, and it is fair to know the difference."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["Your phone shares more than it tells you.", "Run the permission sweep: location, camera, microphone, one question each.", "Does the app need it to work, or does it just want it?"]}]'::jsonb,
  try_this = 'Run the permission sweep together today: open the phone settings, check location, camera and microphone for every app, and turn off anything the app does not need to work.',
  status = 'live'
where id = 'f6e0b096-d016-47fa-a065-5307c7e3c780' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Explorer · Ages 11 to 13 · People and screens", "title": "Group chats without the drama", "body": "A ten minute lesson for you and your child, about staying sane in group chats without losing your friends.", "script": "Ask: how many group chats are you in? Which one is the loudest? And how does it feel when it goes off all evening? Listen properly here. The answer tells you how heavy the phone already is."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can handle any group chat with the three levers: mute it, leave it, or say one kind line.", "why": "Group chats are brilliant and exhausting at the same time. Two hundred messages about nothing, drama at midnight, pressure to reply fast. You have more control than it feels like, and none of it costs you your friends.", "gains": ["I know a chat can be muted without anyone being hurt", "I know how to leave a chat without starting drama", "I can say what I need in a chat in one calm line"]}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "📳", "heading": "Two hundred messages about nothing", "body": "Group chats reward speed. Reply fast and you are in the joke. Reply slow and the chat has moved on. So it starts to feel like a duty: check it, keep up, never miss a night. Here is the secret the apps do not advertise: muting is invisible. Nobody gets told. The chat carries on, and your evening comes back.", "script": "Share your own version honestly: a work chat or family chat that runs hot. Ask your child which chat they would mute tonight if they knew for certain nobody would ever find out. That answer is the real one."}, {"type": "scenario", "phase": "teach", "minutes": 2, "handle": "🏀 Saturday squad", "avatar": "📱", "meta": "Group chat · 62 new messages · 11:12pm", "text": "why is everyone ignoring my message??? i can see who has read it 👀 if you have not replied in 10 minutes you are out of the group", "prompt": "Read this together. What is this message trying to make everyone feel? Does a real friend measure friendship in reply speed? Ask each other: which of the three levers would you pull here, and would you pull it tonight or tomorrow morning?"}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🎚️", "heading": "The three levers", "body": "Lever one, mute: the chat stays, the pings stop, nobody is told. Lever two, leave: allowed, and smoothest with one friendly line first, something like leaving to keep my phone quiet, see you at school. Lever three, speak: one calm line when something actually needs saying, then stop. And one rule over all three: no lever gets pulled at midnight. Mornings are wiser.", "script": "Agree the family version out loud: which lever is the default? Most families land on mute first, leave if muting is not enough, speak when someone is being hurt. Write it somewhere you will both see it."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "A chat you like has turned into two hundred pings a night and you dread opening it. What is the strong move?", "options": [{"text": "Keep up with every message so nobody thinks you are rude", "correct": false, "feedback": "That is the duty feeling talking, and it grows the more you feed it. Muting is invisible. Nobody thinks you are rude, because nobody even knows."}, {"text": "Mute it, catch up once a day, reply to what actually matters", "correct": true, "feedback": "That is lever one, pulled well. Still in the chat, still in the jokes, but the chat runs on your time now instead of running your evening."}, {"text": "Leave with a message about how annoying everyone is", "correct": false, "feedback": "Leaving is allowed, but that exit line becomes the drama, and screenshots of it will outlive the chat. One friendly line, or just mute first and decide later."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "What does muting a group chat actually do?", "options": [{"text": "It tells everyone in the chat that you muted them", "correct": false, "feedback": "Nobody is notified, and that is the whole point. Muting is the quietest move on the phone, which is exactly why it causes no drama."}, {"text": "It quiets the pings for you while the chat carries on, and nobody is told", "correct": true, "feedback": "Exactly. The chat lives on, your notifications go quiet, and no one knows. Your calm is not rude, it is just yours."}, {"text": "It removes you from the group", "correct": false, "feedback": "That is leaving, which is lever two. Muting keeps you in the group with the volume down, which is why it is usually the first lever to try."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["A group chat should not run your evening.", "Three levers: mute it, leave it, or say one kind line.", "Muting is invisible. Your calm is not rude."]}]'::jsonb,
  try_this = 'Pick the loudest group chat on the phone and pull one lever together today: mute it, leave it with a friendly line, or agree the one calm line worth sending.',
  status = 'live'
where id = '07509b2a-6082-478d-97e5-bb583e0b4710' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Explorer · Ages 11 to 13 · Your name online", "title": "Your digital footprint is already real", "body": "A ten minute lesson for you and your child, about searching your own name and owning what comes up.", "script": "Ask: if a new teacher searched your name tonight, what do you think they would find? Take real guesses, both of you. By the end of this lesson you will know instead of guessing, and knowing is always better."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can run the self search, see what is out there with my name on it, and start shaping it on purpose.", "why": "A footprint is not something that starts when you are older. Tagged photos, old comments, usernames: some of it is already out there. This is not a scary thing. It is just a true thing, and true things are easier to handle when you look at them.", "gains": ["I know what a digital footprint is made of", "I can run the self search calmly, with my parent, not alone in a panic", "I know old stuff can often be untagged, deleted or taken down by asking"]}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "👣", "heading": "The footprint you did not choose", "body": "Your footprint has two halves. The half you made: posts, comments, usernames, accounts. And the half other people made about you: tagged photos, the football team page, a mention in someone''s video. Search engines do not check whether you wanted something out there. They just find it. That is why looking is worth it.", "script": "Reassure early: whatever the search finds, nobody is in trouble. This lesson only works if it feels like a shared investigation, not an inspection. Say that out loud before you type anything."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🔎", "heading": "The self search", "body": "Together, search the full name. Then the name plus your town, school or club. Then any usernames. Sort what you find into three piles. Fine: the school website, the swimming results. Meh: an old username, an ancient comment. Needs action: anything you would not want a new teacher to see. For that pile there are real moves: untag, delete, ask the person who posted it, or report it to the platform.", "script": "Do this live on one device, side by side. If something upsetting turns up, stay steady: the plan is the same, untag, ask, report, and none of it is your child''s fault. Finding it together today beats a stranger finding it first."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🌱", "heading": "Plant good footprints", "body": "A footprint is not just a risk to manage. One day a coach, a school or an employer will search this name, and the results are the first impression. The good news: you get a vote. The projects you share, the things you make, the way you talk to people online. Every one of those is a footprint you planted on purpose.", "script": "End this slide on the positive: ask what your child would love someone to find when they search this name in five years. A team, a channel, a project? That answer is a small plan worth keeping."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "The self search turns up an embarrassing photo a friend tagged you in two years ago. What is the strong move?", "options": [{"text": "Panic and never search your name again", "correct": false, "feedback": "Not knowing does not remove it, it just means everyone else can see something you cannot. Now you know, you can act, and this is exactly a two person job."}, {"text": "Untag yourself, then ask your friend to take it down, with a parent in the loop", "correct": true, "feedback": "That is the needs action pile handled properly. Most friends take a photo down the same day you ask. Calm, quick, done."}, {"text": "Post an embarrassing photo of them to make it even", "correct": false, "feedback": "Now there are two embarrassing photos online and one friendship in trouble. Ask first. It works far more often than it feels like it will."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "Who adds to your digital footprint?", "options": [{"text": "Only you, through what you post", "correct": false, "feedback": "Half right. Your posts count, but so do other people''s tags, mentions and photos of you. That other half is exactly why the self search matters."}, {"text": "You and other people, through posts, tags and comments with your name on them", "correct": true, "feedback": "Exactly. Both halves are real, and both show up in a search. You control one half directly, and you have real moves for the other."}, {"text": "Nobody, because everything online disappears after a while", "correct": false, "feedback": "Some things fade, but plenty gets saved, screenshotted or copied. Knowing what is out there beats hoping it vanished."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["Your name already has a story online. Read it first.", "The self search: your name, your usernames, together, calmly.", "What you find you can usually fix. What you plant next, you choose."]}]'::jsonb,
  try_this = 'Run the self search together today: search the full name and any usernames, sort what you find into fine, meh and needs action, and fix one thing.',
  status = 'live'
where id = '44acff35-6e85-4765-b80a-80c2acb4593d' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Explorer · Ages 11 to 13 · Feeling good", "title": "Mood and the scroll", "body": "A ten minute lesson for you and your child, about noticing what the feed does to your mood, and acting on it.", "script": "Ask: after a long scroll, do you usually feel better, worse, or just a bit blank? There is no wrong answer, and it changes day to day. Today you both become the kind of person who notices."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can run the before and after check, so my feed works for my mood instead of against it.", "why": "Feeds are not neutral. Some scrolls leave you laughing, some leave you flat or wound up. The feed is already watching what you do. This lesson is you watching back.", "gains": ["I can name my mood before and after a scroll", "I know which parts of my feed lift me and which drain me", "I know one move to make when a scroll leaves me worse"]}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🌀", "heading": "The scroll is not neutral", "body": "The feed learns what keeps you looking, and shows you more of it. Here is the catch: what keeps you looking is not always what makes you feel good. Arguments hold attention. Perfect lives hold attention. So a feed can slowly fill with things that grip you and drain you at the same time, and it happens without anyone deciding it.", "script": "Be honest about your own feed here: name one thing that grips you but leaves you worse, doomscrolling news, arguments, property you cannot afford. Your honesty gives your child permission to be honest about theirs."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🌡️", "heading": "The before and after check", "body": "Before you open the app, say your mood in one word and a number out of ten. Bored, six. Happy, eight. Scroll as normal. When you stop, check again: one word, one number. That is the whole move. The gap between the two numbers is information about your own feed that nobody else can give you.", "script": "Do a practice run right now on today''s mood, no scrolling needed: one word and a number each. It takes ten seconds, which is the point. A check this small actually gets used."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🧭", "heading": "Act on the answer", "body": "If the number dropped, name what did it. A certain account? A topic? Comparing? Then use the tools the app already gives you: unfollow, mute, not interested. Think of the feed as a pet you are training: reward what lifts you by watching it, remove what drains you. A few weeks of this and the same app feels different, because it is.", "script": "Make the first training move together now if a phone is handy: one unfollow or one mute each. Doing it once beats agreeing to do it later."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "Your check says you were a seven before the scroll and a four after. What is the strong move?", "options": [{"text": "Scroll more to try to get the seven back", "correct": false, "feedback": "The scroll is what took the seven, so more of it rarely gives it back. Moods refill off the app: food, movement, people, daylight."}, {"text": "Name what dragged the number down, then unfollow or mute it", "correct": true, "feedback": "That is acting on the answer. You found the leak and fixed it. Do this a few times and your feed starts working for your mood instead of against it."}, {"text": "Decide feeds are evil and feel guilty for scrolling", "correct": false, "feedback": "Guilt is not the lesson. The feed is not the villain, it is just untrained, and you now hold the exact data needed to train it."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "Why does the before and after check work?", "options": [{"text": "Because it proves screens are bad for you", "correct": false, "feedback": "It often proves the opposite: some scrolls genuinely lift you. The check is not for blaming screens, it is for telling your lifts from your drains."}, {"text": "Because it turns a vague feeling into information you can act on", "correct": true, "feedback": "Exactly. A blank mood after scrolling is easy to shrug off. A seven that became a four is a fact, and facts point at what needs to change."}, {"text": "Because checking your mood makes the feed change by itself", "correct": false, "feedback": "The feed only changes when you use the tools: unfollow, mute, not interested. The check just tells you exactly where to point them."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["Your feed is watching you. The check is you watching back.", "Before and after: one word, one number, every time.", "If the number drops, change the feed, not yourself."]}]'::jsonb,
  try_this = 'Run the before and after check on the next scroll today: one mood word and a number out of ten before, the same after, then unfollow or mute one thing if the number dropped.',
  status = 'live'
where id = '3ecf8a6c-8cbd-40a7-a3e4-8084f456aac5' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Foundation · Ages 4 to 7 · AI and you", "title": "Some voices are not people", "body": "A ten minute lesson for you and your child, about the friendly voices on screens that are clever tools, not people.", "script": "Open with a wondering question: who do we talk to on screens? Grandma on a video call? Now the tricky one: does anything else talk back to us? A speaker, a game character, a talking toy? Today we learn a game called the person check."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can tell when a voice is a clever tool and not a real person.", "why": "Some voices sound warm and friendly but come from a machine. Knowing the difference keeps talking to screens fun and safe.", "gains": ["I know some voices come from machines", "I can play the person check", "I ask my grown up when I am not sure"]}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Voices that talk back", "emoji": "🔊", "body": "Some toys and screens can talk. They sound kind. But they are machines, a bit like a talking torch. They do not have feelings and they can get things wrong.", "script": "Point at something in your home that talks, a speaker, a satnav, a toy. Say: it sounds like a person, but there is no one inside. It is a tool that is very good at sounding friendly. Ask: does the torch love us? No. Same for the talking speaker. Keep it light. This is not scary, just true."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "The person check", "emoji": "🕵️", "body": "When a voice talks to you, play the person check. Ask: person or tool? If you are not sure, ask your grown up. Real people can hug you back. Tools cannot.", "script": "Practise it right now, one voice at a time. Grandma on a video call? Person. The speaker in the kitchen? Tool. A cartoon character who says your name in a game? Tool, even that one. Then set the family rule: whenever a new voice talks to you, we play the person check together."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "The speaker at home answers your question in a kind voice. What do you know?", "options": [{"text": "It is my friend and it loves me", "correct": false, "feedback": "It sounds friendly, and that is clever. But it is a tool with no feelings inside. Your real friends can hug you back."}, {"text": "It is a clever tool, and I can ask my grown up if I am not sure", "correct": true, "feedback": "That is the person check working. Tool, not person. And asking your grown up is always a strong move."}, {"text": "I should tell it my secrets", "correct": false, "feedback": "Secrets are for people we trust, like your grown up. A tool does not need to know them."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "Which one is a real person?", "options": [{"text": "The cartoon who says my name in a game", "correct": false, "feedback": "Saying your name is a clever trick a game can do. It is still a tool, not a person."}, {"text": "Grandma on a video call", "correct": true, "feedback": "Yes. Grandma is a real person, even through a screen. She has feelings and she loves you."}, {"text": "The voice in the speaker", "correct": false, "feedback": "It talks well, but there is no one inside. It is a machine that is good at sounding like us."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["Some voices are tools, even the friendly ones.", "Play the person check: person or tool?", "When you are not sure, your grown up always knows."]}]'::jsonb,
  try_this = 'Play the person check today: every time a voice or character talks from a screen, ask together, person or tool?',
  status = 'live'
where id = '89530f9a-4897-4df7-8dc4-fa8d6904dc4c' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Foundation · Ages 4 to 7 · When it turns unkind", "title": "When screens make you sad", "body": "A ten minute lesson for you and your child, about what to do the moment a screen makes them feel sad or scared.", "script": "Start gently: has anything on a screen ever given you a funny feeling in your tummy? Maybe something scary popped up, or someone was unkind in a game. Let your child answer without fixing anything yet. Today we make one simple family rule for those moments: stop and tell."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can stop and tell my grown up when a screen makes me feel bad.", "why": "Screens sometimes show things that feel wrong. That is never your fault. There is one move that always works.", "gains": ["I listen to my funny tummy feeling", "I know the stop and tell rule", "I know I am never in trouble for telling"]}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Your tummy knows first", "emoji": "🦋", "body": "Sometimes a screen shows something unkind or scary. Your tummy feels funny, or your face goes hot. That feeling is your body saying: get help.", "script": "Name some examples at their level: a scary video that popped up, a mean message in a game, a picture that felt wrong. Say clearly: if that ever happens, it is not because you did anything bad. The funny feeling is a superpower. It tells us it is time for the rule."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Stop and tell", "emoji": "🛑", "body": "Stop: put the screen down. Tell: find your grown up and say what happened. That is the whole move. You will never be in trouble for telling.", "script": "This is the promise that makes the rule work, so say it word for word: if you stop and tell, I will never be cross with you, whatever was on the screen. Then practise once for pretend. Hand them a cushion as the screen, act out something silly popping up, and let them put it down, come to you and tell. Cheer the telling, not the thing."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "A scary picture pops up in your game. What is the strong move?", "options": [{"text": "Keep playing and try not to look at it", "correct": false, "feedback": "Trying to be brave all on your own is hard work. The strong move is easier: put it down and tell your grown up."}, {"text": "Stop, put the screen down and tell your grown up", "correct": true, "feedback": "That is stop and tell, done perfectly. Your grown up can sort it, and you are never in trouble for telling."}, {"text": "Hide the screen so no one finds out", "correct": false, "feedback": "Hiding keeps the yucky feeling stuck inside you. Telling lets it out, and telling is always safe in our family."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "What happens when you tell your grown up about something bad on a screen?", "options": [{"text": "I get in trouble", "correct": false, "feedback": "Never. Telling is the strong move, and the promise in our family is that telling is always safe."}, {"text": "They help me, and I am never in trouble for telling", "correct": true, "feedback": "Exactly. Telling is how grown ups can help. It is the bravest, strongest move there is."}, {"text": "The screen gets thrown away", "correct": false, "feedback": "No. Screens are not the villain. We sort out the bad bit together, and playing can be fun again."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["Your funny tummy feeling is a superpower.", "Stop and tell: put it down, find your grown up.", "Telling is brave, and you are never in trouble for it."]}]'::jsonb,
  try_this = 'Agree the stop and tell rule today and practise it once for pretend, so the real moment feels easy.',
  status = 'live'
where id = 'ab10cda5-a7ac-4dc2-a5ae-1236641f6f3c' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Foundation · Ages 4 to 7 · Being you", "title": "Me on a screen and me in real life", "body": "A ten minute lesson for you and your child, about pictures on screens and the real things they show.", "script": "Open with a giggle: if I showed you a photo of a biscuit, could you eat it? Why not? Let them explain it to you. That little idea, a picture of a thing is not the thing, is the whole lesson, and it gets big later."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can tell the difference between a picture of a thing and the real thing.", "why": "Screens are full of pictures. Pictures are fun, but they are not the real thing, and real you is always more than any picture.", "gains": ["I know a picture of a thing is not the thing", "I can play the biscuit test", "I know real me is more than any photo"]}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "The biscuit test", "emoji": "🍪", "body": "You cannot eat a photo of a biscuit. You cannot hug a photo of Grandma. A picture shows a thing, but it is not the thing. That is the biscuit test.", "script": "Play it around the room with a screen: photo of a dog, can it lick you? Photo of a cake, can you taste it? Video of the sea, can it get you wet? Let them shout no each time. Then land it: pictures are lovely, and they are only ever pictures."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Real you is bigger", "emoji": "🪞", "body": "A photo of you shows one tiny moment. Real you laughs, runs, changes and grows. No picture can hold all of you.", "script": "Find a photo of your child looking grumpy or silly and ask: is this you? Sort of! It is one second of you. Ask what the photo cannot show: your jokes, your hugs, how kind you are. Then say it plainly: people on screens are like that too. We only ever see their pictures, never the whole person."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "You see a photo of a giant ice cream on a screen. Can you eat it?", "options": [{"text": "Yes, if I lick the screen", "correct": false, "feedback": "That would taste of screen! It is a picture of ice cream, and the biscuit test says a picture is not the thing."}, {"text": "No, it is a picture of ice cream, not real ice cream", "correct": true, "feedback": "The biscuit test, passed! Pictures show things, but they are not the things."}, {"text": "Yes, if I ask very nicely", "correct": false, "feedback": "Asking nicely is lovely, but no amount of asking turns a picture into pudding. A picture is not the thing."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "A photo of you looks grumpy. Does that mean you are a grumpy person?", "options": [{"text": "Yes, the photo proves it", "correct": false, "feedback": "A photo only holds one second. You have millions of seconds, and most of yours are not grumpy."}, {"text": "No, a photo shows one moment, and real me is much more", "correct": true, "feedback": "Yes. Real you is bigger than any picture. That is true for everyone you see on screens too."}, {"text": "Yes, and I will be grumpy forever", "correct": false, "feedback": "One grumpy second does not make a grumpy you. Real you changes and grows all the time."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["A picture of a thing is not the thing.", "Play the biscuit test on any screen picture.", "Real you is bigger than every photo of you."]}]'::jsonb,
  try_this = 'Play the biscuit test at teatime: find a photo of food on a screen and laugh together about why nobody can eat it.',
  status = 'live'
where id = 'c5c67ffb-9a4f-485e-884e-292cdfe88e22' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Foundation · Ages 4 to 7 · True or not", "title": "Real or pretend?", "body": "A ten minute lesson for you and your child, about sorting what screens show into stories, adverts and true things.", "script": "Open with: is a cartoon real? How do you know? Enjoy the answer. Then say: screens show three kinds of things, and today we learn to sort them into three boxes, like tidying toys."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can sort screen things into three boxes: story, advert or true.", "why": "Screens mix up pretend things, selling things and true things. Sorting them is a game, and it makes you clever about what you watch.", "gains": ["I know stories are pretend fun", "I know adverts want me to want things", "I can play the three boxes game"]}, {"type": "diagram", "phase": "teach", "minutes": 2, "heading": "The three boxes", "steps": [{"emoji": "📖", "title": "Story", "text": "Pretend, made for fun. Cartoons and dragons live here."}, {"emoji": "🛒", "title": "Advert", "text": "Made to sell. It wants you to want something."}, {"emoji": "✅", "title": "True", "text": "Really happened. Real animals, real places, real news."}], "script": "Walk the three boxes slowly. The tricky one is the advert box, so give it extra time: an advert is not naughty, it just has a job, and its job is to make you want the toy or the cereal. Ask: can you think of a video that wanted you to want something? Sorting, not banning, is the skill."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Playing the three boxes", "emoji": "🧺", "body": "When you watch something, ask: which box? Story, advert or true? If you are not sure, sort it with your grown up.", "script": "Practise on things they know. A unicorn cartoon? Story box. A video where a happy family eats a new cereal? Advert box. A nature clip of a real lion? True box. When one is hard to sort, say: tricky ones are the best ones, we sort those together."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "A video says a toy will make you the happiest child in the world. Which box?", "options": [{"text": "The true box, because the video said so", "correct": false, "feedback": "Videos can say anything. This one has a job, to make you want the toy. That is the advert box."}, {"text": "The advert box, because it wants me to want the toy", "correct": true, "feedback": "Sorted! It might look fun and true, but its job is selling. Straight into the advert box."}, {"text": "The story box, because it is just fun", "correct": false, "feedback": "Close, because adverts do use fun and pretend. But this one has a job: to sell the toy. That makes it an advert."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "What is an advert''s job?", "options": [{"text": "To tell me true things", "correct": false, "feedback": "Adverts can use true bits, but that is not their job. Their job is to make you want something."}, {"text": "To make me want something", "correct": true, "feedback": "That is it. Not naughty, just a job. And now you can spot it, the advert box has no tricks left."}, {"text": "To scare me", "correct": false, "feedback": "Adverts almost never want to scare you. They want you to want things. That is how you spot them."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["Screens show stories, adverts and true things.", "Play the three boxes: which box is this?", "Tricky ones get sorted with your grown up."]}]'::jsonb,
  try_this = 'Watch one advert together today and sort it into its box: story, advert or true.',
  status = 'live'
where id = '255374f8-d47d-4553-8dad-5e795844c9aa' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Foundation · Ages 4 to 7 · Made by someone", "title": "Someone made that", "body": "A ten minute lesson for you and your child, about the real people who make the pictures, songs and games we love.", "script": "Open with their own work: point at a drawing they made and ask: who made this? You did! How would you feel if someone said they made it? Hold that feeling. Today it grows into a game about everything on screens."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can remember that everything on a screen was made by someone.", "why": "Every game, song and picture was made by a person, like your drawings. Knowing that helps us treat their work kindly.", "gains": ["I know screen things have makers", "I can play the maker game", "I ask before using someone else''s work"]}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Everything has a maker", "emoji": "🎨", "body": "Someone drew that cartoon. Someone wrote that song. Someone built that game. Screen things do not grow on trees. People make them, like you make your drawings.", "script": "Make it real with one example they love. Their favourite cartoon: real people drew every single picture in it, thousands of them. Their favourite song: someone hummed it first in their kitchen. The wow here is the point: behind every screen thing is a person who worked hard."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "The maker game", "emoji": "🔍", "body": "When you see something you love on a screen, play the maker game. Ask: who made it? And if you want to use it, ask your grown up to help check first.", "script": "Connect it back to their drawing: you would want someone to ask before taking your picture, so we ask before taking other people''s. Play one round now: pick the thing on a screen they love most and wonder together about its maker. What do they look like? Where do they work? Makers become real people this way."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "You find a lovely picture on a screen and want it for your poster. What is the strong move?", "options": [{"text": "Just take it, screen things are free", "correct": false, "feedback": "It feels free, but someone made that picture, like you make yours. Taking without asking is not our move."}, {"text": "Ask your grown up to help check whose it is", "correct": true, "feedback": "That is the maker game. Someone made it, so we check before we use it. Makers love being asked."}, {"text": "Say you made it yourself", "correct": false, "feedback": "Remember your drawing? Saying you made someone else''s work would give the real maker a sad tummy."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "Who does a song belong to?", "options": [{"text": "Whoever hears it first", "correct": false, "feedback": "Hearing a song is free fun, but the song still belongs to the person who made it."}, {"text": "The person who made it", "correct": true, "feedback": "Yes. Songs, pictures and games belong to their makers, just like your drawings belong to you."}, {"text": "The screen it plays on", "correct": false, "feedback": "The screen is just the window. The song belongs to its maker, the person who created it."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["Every screen thing was made by a real person.", "Play the maker game: who made it?", "Ask before you use it, like you would want to be asked."]}]'::jsonb,
  try_this = 'Play the maker game today: pick one song, picture or game your child loves and wonder together about who made it.',
  status = 'live'
where id = 'd0038b85-e692-4093-bd18-7abf5b040c18' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Foundation · Ages 4 to 7 · Private stuff", "title": "My privacy shield", "body": "A ten minute lesson for you and your child, about the four things our family never tells a screen.", "script": "Open with: what does a shield do? It keeps the important stuff safe behind it. Today we build one for screens, with four special words behind it, and one move to shout when a screen asks for them: shield up."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can keep my four shield words safe when a screen asks for them.", "why": "Some things about you are just for your family. A shield keeps them safe, and there is one move to make when a screen asks.", "gains": ["I know my four shield words", "I can shout shield up", "I fetch my grown up when a screen asks about me"]}, {"type": "diagram", "phase": "teach", "minutes": 2, "heading": "The four shield words", "steps": [{"emoji": "🙋", "title": "My name", "text": "My real full name stays behind the shield."}, {"emoji": "🏫", "title": "My school", "text": "Where I go to school is family stuff."}, {"emoji": "🏠", "title": "My home", "text": "Where I live stays with us."}, {"emoji": "🔑", "title": "Passwords", "text": "Passwords are keys. Keys stay hidden."}], "script": "Go through the four slowly and let your child say each one back to you. Explain the why without fear: these four tell a stranger where to find you or how to get into your things, so they live behind the shield. Screens and games sometimes ask for them, often with a prize attached. The answer is never typing. The answer is fetching you."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Shield up", "emoji": "🛡️", "body": "If a screen asks for a shield word, shout shield up! Type nothing. Fetch your grown up. They decide what is safe.", "script": "Practise the move with your body: arms crossed like a shield, then off to find you. Make it a game, and make the promise out loud: coming to fetch me is never wrong, even if it turns out fine. Sometimes you will type things in together, and that is fine too. The rule is simply: a grown up decides, never the screen."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "A game says: tell us your name and school to win a prize! What do you do?", "options": [{"text": "Type it quickly to win the prize", "correct": false, "feedback": "Prizes are exactly how screens ask for shield words. That is the moment for shield up, not typing."}, {"text": "Shield up! Type nothing and fetch your grown up", "correct": true, "feedback": "Perfect. Shield words stay behind the shield, and your grown up decides what is safe."}, {"text": "Type just the school, not your name", "correct": false, "feedback": "Half a shield word is still a shield word. School stays behind the shield too. Fetch your grown up."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "Which of these stays behind your shield?", "options": [{"text": "Your favourite colour", "correct": false, "feedback": "You can tell anyone your favourite colour! The shield is only for the four special words."}, {"text": "Where you live and your passwords", "correct": true, "feedback": "Yes. Name, school, home and passwords. Those four stay behind the shield, always."}, {"text": "Your favourite dinosaur", "correct": false, "feedback": "Dinosaur chat is free for everyone. The shield guards the four special words, not the fun stuff."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["Four shield words: name, school, home, passwords.", "When a screen asks, shield up and type nothing.", "Fetch your grown up. They decide, not the screen."]}]'::jsonb,
  try_this = 'Draw a shield together today and write the four shield words on it: name, school, home, passwords.',
  status = 'live'
where id = 'd6acfb58-0605-49b6-95ab-e087e66729e3' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Foundation · Ages 4 to 7 · People and screens", "title": "Kind words on screens", "body": "A ten minute lesson for you and your child, about talking through screens the way we talk face to face.", "script": "Open with: when you say something kind to someone, what happens to their face? And something unkind? Faces show us where our words land. Screens hide the faces, and that is the whole puzzle we solve today."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can use the face test before my words go into a screen.", "why": "Words on screens land in real people, even when you cannot see their faces. One little test keeps your words kind.", "gains": ["I know real people are behind screens", "I can use the face test", "I make my words kind before they go"]}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "The hidden faces", "emoji": "🙈", "body": "When you talk through a screen, you cannot see the other person''s face. But they are real, and your words still land in their tummy.", "script": "Try a tiny experiment: say something kind to your child and watch their face light up. Then ask: if I said that through a screen, would it still feel nice? Yes! Kind and unkind words both keep their power through screens. We just lose the face that shows us where they landed."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "The face test", "emoji": "😊", "body": "Before your words go into a screen, do the face test: imagine the person standing right here. Would you say it to their face? If yes, send it. If no, change it.", "script": "Practise out loud with pretend messages. Good game! Face test? Pass. You are rubbish at this! Face test? Fail, so we change it before it goes. At this age you are usually beside them at the screen, so make the face test a thing you say together: does it pass the face test?"}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "Your friend''s tower breaks in a game and you want to say something. What passes the face test?", "options": [{"text": "Ha ha, you are rubbish at building", "correct": false, "feedback": "Imagine their face if you said it standing next to them. That would sting. The face test says change it."}, {"text": "Bad luck! Want to build it again together?", "correct": true, "feedback": "That passes the face test beautifully. Kind to their face, kind through the screen."}, {"text": "Nothing, just laugh about it with someone else", "correct": false, "feedback": "Laughing behind a screen still lands on a real person. The face test works for giggles too."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "Why do we use the face test?", "options": [{"text": "Because screens might tell on us", "correct": false, "feedback": "The reason is warmer than that. It is because a real person is on the other side, feelings and all."}, {"text": "Because a real person with real feelings gets our words", "correct": true, "feedback": "Exactly. The screen hides their face, not their feelings. The face test remembers them for us."}, {"text": "Because unkind words break the screen", "correct": false, "feedback": "Screens do not mind words at all. People do. That is who the face test protects."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["Real people are behind screens, feelings and all.", "Do the face test: would I say it to their face?", "Kind through a screen is still kind. It counts."]}]'::jsonb,
  try_this = 'Practise the face test today: before anything gets typed or said into a screen, say it out loud first as if the person is in the room.',
  status = 'live'
where id = 'e3c79270-ca52-4ae7-8151-873d85768ceb' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Foundation · Ages 4 to 7 · Your name online", "title": "The internet remembers", "body": "A ten minute lesson for you and your child, about how screens keep things, and the one move before anything goes on them.", "script": "Open with the family photo album if you have one: these photos are years old and still here. Screens keep things too, but their album can be copied by other people. That is why our family has one rule before anything goes on a screen: ask before it goes."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can ask before a photo or my words go on the internet.", "why": "The internet is like a giant photo album that other people can copy. So before anything goes in, we ask first.", "gains": ["I know the internet can keep things", "I ask before it goes", "I get asked before my photo goes anywhere too"]}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "The album everyone can copy", "emoji": "📚", "body": "When a photo or words go on the internet, they can stay a long time. Other people can copy them. It is hard to get things back out.", "script": "Use a real object: draw a little picture together, then pretend to photocopy it five times and hand the copies around the room. Now try to get them all back. Tricky! That is the internet''s album. Not scary, just worth knowing before things go in. Keep the tone matter of fact: this is simply how the thing works."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Ask before it goes", "emoji": "🙋", "body": "Before a photo or message goes on the internet, ask before it goes. Ask the people in the photo. Ask your grown up. And grown ups ask you before your photo goes anywhere too.", "script": "The last line is the magic, so make the promise out loud: from today I will ask you before I share a photo of you, and you can say no. Being asked is how children learn asking. Then practise one round on an old family photo: who is in it? So who do we ask? Everyone in it, plus a grown up."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "You took a funny photo of your sister and want to send it to everyone. What is the strong move?", "options": [{"text": "Send it fast, it is so funny", "correct": false, "feedback": "Funny to you might feel yucky to her, and sent photos are hard to get back. Ask before it goes."}, {"text": "Ask your sister and your grown up first", "correct": true, "feedback": "That is ask before it goes. Everyone in the photo gets a say, and your grown up checks it is safe."}, {"text": "Send it to just a few people", "correct": false, "feedback": "A few people can copy it to lots of people. The move is not fewer sends, it is asking first."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "What can happen to a photo once it goes on the internet?", "options": [{"text": "It disappears at bedtime", "correct": false, "feedback": "Photos on the internet do not sleep. They can stay and be copied, which is why we ask first."}, {"text": "It can stay a long time and be copied", "correct": true, "feedback": "Yes. The internet is an album other people can copy. Asking first is the strong move."}, {"text": "Only the sender can ever see it", "correct": false, "feedback": "Once a photo is sent it can travel to lots of screens. That is why asking comes before sending."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["The internet is an album other people can copy.", "Ask before it goes: the people in it, then your grown up.", "You get asked too. Your photo, your say."]}]'::jsonb,
  try_this = 'Pick one family photo today and practise ask before it goes, with everyone in the photo saying yes first.',
  status = 'live'
where id = '5fb2a193-5f80-4dca-8ba3-2ceb14462579' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Foundation · Ages 4 to 7 · Feeling good", "title": "Screens, sleep and growing bodies", "body": "A ten minute lesson for you and your child, about sleep, growing, and where screens spend the night.", "script": "Open with: what happens when you sleep? Bodies grow, brains tidy up the day, poorly bits mend. Sleep is when the magic happens. Today we work out why screens spend the night in a different room, and we give them a bed of their own."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can put screens to bed in their own bed, outside my bedroom.", "why": "Your body does its best growing while you sleep. Screen light keeps brains awake, so screens sleep in their own bed, in another room.", "gains": ["I know sleep helps my body grow", "I know screen light tells brains to stay awake", "I can tuck screens into the screen bed"]}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Sleep is when you grow", "emoji": "🌙", "body": "While you sleep, your body grows and your brain tidies up your day. Sleep is not boring. Sleep is builder time.", "script": "Sell sleep as the magic it is: growing happens at night, learning gets glued in at night, even scrapes mend faster while you sleep. Ask what they are getting good at, then tell them: tonight, while you sleep, your brain will practise that all by itself. This is why bedtime is worth protecting."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Screen light says wake up", "emoji": "🔆", "body": "Screens shine bright light, a bit like little suns. Bright light tells your brain: it is daytime, stay awake! That makes sleeping harder.", "script": "Keep the science this simple: brains use light to know when it is bedtime. A bright screen near bedtime tells the brain the wrong time, like a clock that fibs. No villain here, screens just shine. So the fix is not less love for screens. It is a better bedtime for them."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "The screen bed", "emoji": "🛏️", "body": "Screens get their own bed, outside the bedrooms. At night, every screen gets tucked in there, and it stays there until morning.", "script": "Make it real today: choose the spot together, the kitchen, the hall, wherever the chargers can live. Let your child decorate it or give it a name. Then say the rule warmly, and for everyone: screens sleep in the screen bed, and that includes ours. Children spot a rule that only applies to them from a mile away."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "It is nearly bedtime and the tablet is still playing. What is the strong move?", "options": [{"text": "Bring it to bed, just this once", "correct": false, "feedback": "Its bright light would tell your brain to stay awake, right when growing time starts. The tablet has its own bed."}, {"text": "Tuck the tablet into the screen bed and head for yours", "correct": true, "feedback": "That is the screen bed working. The tablet sleeps in its spot, and your body gets its full building night."}, {"text": "Hide it under your pillow for the morning", "correct": false, "feedback": "Under the pillow is still in the bedroom, and screens are wrigglers. The screen bed keeps bedtime easy."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "Why do screens sleep outside the bedroom?", "options": [{"text": "Because screens are naughty", "correct": false, "feedback": "Screens are not naughty at all. They just shine like little suns, and suns do not belong at bedtime."}, {"text": "Because their bright light tells brains to stay awake", "correct": true, "feedback": "That is it. Bright light says daytime to a brain. Outside the bedroom, your brain hears bedtime loud and clear."}, {"text": "Because bedrooms are too small for screens", "correct": false, "feedback": "There is plenty of room really! It is the light, not the size. Bright light near bedtime makes sleep harder."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["Sleep is builder time for bodies and brains.", "Screen light says wake up, so screens sleep somewhere else.", "Tuck them into the screen bed. Every screen, every night."]}]'::jsonb,
  try_this = 'Make the screen bed today: choose a spot outside the bedrooms where every screen in the house sleeps at night.',
  status = 'live'
where id = '4bd125d1-4790-4153-9fd1-7cf3865af0f7' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Independent · Ages 16 plus · AI and you", "title": "From user to maker, with your judgement in charge", "body": "A ten minute lesson for the two of you, about using AI to make real things while your judgement stays in charge.", "script": "Open as equals: what has each of you actually used AI for this week, and was the result honestly any good? Share your own miss first. This lesson is a swap of craft, not a lecture."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can use AI as a tool for making things, and I stay the editor of everything that carries my name.", "why": "AI can draft faster than any human. It cannot decide what is true, what is fair or what sounds like you. That judgement is the part people will pay you for.", "gains": ["I can brief AI properly instead of typing one vague line", "I check and correct AI output before I trust it", "I know what my judgement adds that the tool cannot"]}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Brief it like a colleague", "emoji": "🛠️", "body": "The difference between a useless answer and a good one is usually the brief. Give it context, constraints and a role: who the work is for, what good looks like, what to avoid. Then ask for three options, not one answer. You are not typing a wish. You are briefing a very fast junior who knows nothing about your life.", "script": "Swap prompt craft like colleagues. Each of you rewrite the same weak prompt, something real like a complaint email or a revision plan, and compare what the better brief changed."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "The editor''s pass", "emoji": "✒️", "body": "Nothing AI touched goes out under your name until it has had the editor''s pass. Three checks. Is every fact actually true? Does it say anything you do not believe or cannot back? Does it sound like you and not like a press release? Fix all three, and it is yours. Skip them, and you have signed someone else''s work.", "script": "Talk about the stakes as adults: a made up reference in a job application, an invented figure in an essay. The person who submits it owns the mistake, not the tool. That is the whole case for the pass."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Judgement is the job", "emoji": "🧭", "body": "Work that AI can do cheaply stops being paid work. What stays valuable is the person who can brief well, spot the weak output, and take responsibility for the final call. Using AI does not make you a fraud. Shipping its mistakes without checking does.", "script": "Ask each other where this is already landing: which tasks in your own work or study have quietly become AI shaped in the last year, and what still needs a human signature?"}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "AI drafts your cover letter. It reads beautifully, but one line stretches your experience beyond the truth. What is the strong move?", "options": [{"text": "Send it. It sounds professional and everyone stretches a little", "correct": false, "feedback": "The tool wrote the stretch, but your name signs it. One overstated claim can undo a genuinely good application, and the interview will find it."}, {"text": "Run the editor''s pass: fix the claim, cut what is not you, rewrite it into your own voice", "correct": true, "feedback": "That is the move. The draft saved you time, the pass made it true and made it yours. That combination is exactly what strong use of AI looks like."}, {"text": "Bin the draft and start from a blank page. AI has no place in job applications", "correct": false, "feedback": "The tool was not the problem. The unchecked claim was. A fast draft plus a proper editor''s pass beats both blind trust and a blank page."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "What is the editor''s pass?", "options": [{"text": "A rule that AI must never be used for anything that matters", "correct": false, "feedback": "Refusing the tool is not the skill. Plenty of good work now starts with a draft. The skill is what you do to that draft before it carries your name."}, {"text": "Checking, correcting and rewriting anything AI touched until it is true and sounds like you", "correct": true, "feedback": "Exactly. Facts checked, claims you stand behind, your own voice. After the pass the work is genuinely yours."}, {"text": "Running the output through a second AI to check the first one", "correct": false, "feedback": "A second model can catch slips, but it cannot take responsibility. Somewhere a person has to know the facts and make the call. That person is you."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["AI drafts fast. You decide what is true and what is you.", "Give everything the editor''s pass before it carries your name.", "The judgement is the job. Keep yours sharp."]}]'::jsonb,
  try_this = 'Each of you uses AI on one real task today, then you run the editor''s pass out loud and compare what you changed and why.',
  status = 'live'
where id = 'be8dac4e-b14f-4403-88c7-323f660db908' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Independent · Ages 16 plus · When it turns unkind", "title": "Backing someone up without going down with them", "body": "A ten minute lesson for the two of you, about supporting someone who is being torn apart online without becoming the next target.", "script": "Start with a memory each, as equals: a pile on you both remember watching. What happened to anyone who stepped in? Neither of you needs to have got it right at the time."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can support someone being targeted online without making myself the next target, and I know when reporting beats replying.", "why": "Silence reads as agreement to the person being targeted. But wading into a pile on usually feeds it. There is a third option, and it works.", "gains": ["I know why public fights make a pile on worse", "I can back the target privately and report properly", "I know which situations need an adult or the police, not a reply"]}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Why the pile on wins the reply game", "emoji": "🔥", "body": "A pile on runs on attention. Every angry reply, even a defence, pushes it higher up more feeds and hands the crowd fresh content. The target gets no relief, and the defender often becomes the next course. You cannot out shout a pile on. You can starve it and outflank it.", "script": "Compare notes as adults: has either of you ever replied in anger and made something bigger? What would starving it have looked like instead?"}, {"type": "scenario", "phase": "teach", "minutes": 2, "handle": "Year 13 group", "avatar": "😶", "meta": "Group chat · 41 members · 22:14", "text": "Everyone seen Kian''s retake results? 💀💀 Third time lucky mate. Someone make it a sticker. [14 laughing reacts]", "prompt": "Kian is in this chat, reading everything. What actually helps him right now?", "script": "Read it together and sit in Kian''s seat for a moment before answering. The reacts are the crowd. The question is what a decent person does that actually works."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Private first", "emoji": "💬", "body": "The move is Private first. Message the person, not the thread: saw it, it is not okay, I am around. That one message breaks the loneliest part of being targeted. Then report the worst content through the platform, quietly. Say something public only if it is calm, brief and factual. And when it is threats, private images or someone at risk, it goes above the chat: a trusted adult, the platform, and in the UK the police or CEOP for the serious end. That is scale, not grassing.", "script": "Draft the private message together, one sentence each. Agree it should not ask the target to do anything. It just ends the silence."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "A mate is getting shredded in a big group chat and the jokes keep coming. What is the strong move?", "options": [{"text": "Roast the ringleader back harder. Fight fire with fire", "correct": false, "feedback": "Now the chat has two targets and better content. The pile on feeds on exactly this. Your mate needs relief, not a second front."}, {"text": "Message your mate privately, report the worst messages, and add one calm line in the chat only if it feels safe to", "correct": true, "feedback": "Private first, working exactly as designed. The target hears they are not alone, the platform gets the evidence, and you gave the crowd nothing to feed on."}, {"text": "Leave the chat quietly so you are not part of it", "correct": false, "feedback": "Understandable, and sometimes stepping away is right for you. But to the target, silence from everyone reads as everyone agreeing. One private message costs little and changes their whole night."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "When does reporting beat replying?", "options": [{"text": "Never. If you really back someone you say it publicly, whatever it costs", "correct": false, "feedback": "Loyalty is not the same as tactics. A public war usually costs the target more. The brave move is the one that actually helps."}, {"text": "When the content breaks rules, when there are threats or private images, or when any reply would just feed it", "correct": true, "feedback": "That is the judgement in one line. Reporting removes content and creates a record. Replies mostly create momentum."}, {"text": "Only when you are the one being targeted", "correct": false, "feedback": "Reports from witnesses matter, often more, because they show it is not one person''s word alone. You do not need to be the target to pull that lever."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["You cannot out shout a pile on, so do not try.", "Private first: back the person, report the content.", "Threats and private images go above the chat, every time."]}]'::jsonb,
  try_this = 'Next time either of you sees a pile on, use Private first: message the person being targeted, report the worst of it, then tell each other how it went.',
  status = 'live'
where id = '413104f9-1fdf-4fdb-a625-44bd63bc89ff' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Independent · Ages 16 plus · Being you", "title": "Your identity is yours to write, so write it", "body": "A ten minute lesson for the two of you, about deciding who you are online before employers, admissions teams and strangers decide for you.", "script": "Ask each other, both directions: if a stranger read only your last month of posts and chats, what kind of person would they meet? Answer for yourselves before answering for each other."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can present myself online on purpose, in the right register for each room, without ever faking who I am.", "why": "You are about to be read by universities, employers and people you have not met. The record exists either way. The only question is whether you wrote it.", "gains": ["I know my online self is already public writing", "I can shift register between rooms without being fake", "I use the byline test before I post"]}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "You are already published", "emoji": "📖", "body": "Group chats get screenshotted. Photos get tagged. Old accounts sit in search results. Whether you meant to or not, there is already a published version of you, and adult life is about to start reading it. Authors edit. Passengers just get quoted.", "script": "Swap honestly: the oldest thing online with your name on it that each of you can remember. Would you write it the same way today?"}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Different rooms, same person", "emoji": "🎭", "body": "You talk one way with your mates and another way in an interview. That is not fake. It is register, and every adult does it. The line is simple: every version of you can talk differently, but no version of you gets to say things you do not believe. Change the volume, never the values.", "script": "Test the line together with real examples: banter that is just register, versus a persona that says things the real you would not stand behind. Where exactly does it flip?"}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "The byline test", "emoji": "✍️", "body": "Before you post, comment or share, put your full name under it in your head, like a byline on an article. Would you stand by it in an interview, at the family table, to the person it is about? If yes, publish. If no, that is not your voice, it is a costume, and costumes end up in screenshots.", "script": "Each pick one thing you nearly posted recently and run the byline test on it together. Passing is not the point. Practising the pause is."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "You have typed a savage joke about a classmate into the group chat. It would land. You also have a university interview next month. What is the strong move?", "options": [{"text": "Send it. Group chats are private", "correct": false, "feedback": "No chat with more than two people stays private. One screenshot and the joke has your name on it forever, in rooms you cannot see."}, {"text": "Run the byline test. If you would not own it with your name attached in any room, rewrite it or let it go", "correct": true, "feedback": "That is authorship. You can still be funny. You just make sure the funny version is one the real you signs."}, {"text": "Stop posting anything at all until every application is done", "correct": false, "feedback": "Hiding is not authorship, and an empty record says nothing in your favour. The stronger play is writing things you would be glad to be found saying."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "What is the byline test?", "options": [{"text": "Checking your spelling and grammar before you post", "correct": false, "feedback": "Worth doing, but that polishes the words. The byline test checks something bigger: whether you stand behind them."}, {"text": "Imagining your full name printed under the post and asking if you would stand by it in any room", "correct": true, "feedback": "Exactly. You are the author of your record either way. The test just makes sure you are writing on purpose."}, {"text": "Making separate anonymous accounts so nothing links back to you", "correct": false, "feedback": "Anonymity is thinner than it looks, and a self you have to hide is a warning sign in itself. The test builds a self that does not need hiding."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["There is already a published version of you. Be its author.", "Change the volume for the room, never the values.", "Run the byline test, then post like you mean it."]}]'::jsonb,
  try_this = 'Before either of you posts anything today, run the byline test out loud: would you stand by it with your full name under it, in any room?',
  status = 'live'
where id = '10fb0d4f-9667-45a0-8033-b807a9e27ea8' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Independent · Ages 16 plus · True or not", "title": "Your news diet, chosen on purpose", "body": "A ten minute lesson for the two of you, about feeding yourselves information on purpose instead of swallowing whatever the feed serves.", "script": "Open as equals: where did each of you get your news this week, honestly? Not where you think you should. Where you actually did."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can build an information diet I chose on purpose, instead of one an algorithm chose for me.", "why": "Whoever picks your information picks a lot of your opinions. Right now, for most people, that is a recommendation system built for attention, not truth.", "gains": ["I know why my feed serves anger first", "I have three sources I chose on purpose", "I check my chosen sources before I share anything big"]}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Fed, or feeding yourself", "emoji": "🍽️", "body": "The default feed is not trying to inform you. It is trying to keep you. Anger, fear and outrage hold attention longest, so they get served first, whatever is actually true or actually important. Eat only what you are handed and your worldview is a menu someone else wrote.", "script": "Compare feeds side by side for two minutes, as equals. What is each algorithm apparently sure you both want? Say what surprised you about the other person''s."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "The chosen three", "emoji": "📰", "body": "The move is the chosen three. Pick three sources on purpose and by name: one solid news source, one for your field or your obsession, and one honest voice you disagree with. Check those first, most days. The feed does not have to go. It just becomes the pudding instead of the meal.", "script": "Build both lists now, out loud. Push each other on the third slot: a disagreeing source you respect, not one you keep around to laugh at."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "A big story breaks and your feed floods with furious thirty second clips. You want to post about it. What is the strong move?", "options": [{"text": "Share the most powerful clip while it is still trending", "correct": false, "feedback": "The clip was chosen for heat, not accuracy, and early clips are wrong at the worst moments. If it turns out false, the correction never travels as far as your share did."}, {"text": "Check your chosen three first, then share once you know what actually happened", "correct": true, "feedback": "That is the diet doing its job. Ten minutes with sources you picked on purpose beats an hour of clips picked to keep you angry."}, {"text": "Assume it is all fake and ignore the story completely", "correct": false, "feedback": "Total cynicism is as blind as total trust, and it hands the field to whoever shouts loudest. You built the chosen three exactly so you do not have to guess."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "Why does the chosen three include a source you disagree with?", "options": [{"text": "So you can screenshot their worst takes and dunk on them", "correct": false, "feedback": "That is keeping an opponent, not a source. The point is picking a disagreeing voice honest enough to teach you something."}, {"text": "Because a diet of pure agreement makes you easier to fool, and it shows you where your own case is weak", "correct": true, "feedback": "Exactly. If you only ever hear your own side, you never find out which of your arguments would survive contact. The disagreeing source is training, not betrayal."}, {"text": "Because every disagreement means the truth sits exactly in the middle", "correct": false, "feedback": "Sometimes one side is simply right. Reading across the divide is not about splitting the difference. It is about knowing the whole map before you place yourself on it."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["The default feed is a menu someone else wrote.", "Pick your chosen three and eat there first.", "The feed can stay. As pudding, not the meal."]}]'::jsonb,
  try_this = 'Today you each name your chosen three sources, including one you disagree with, and pin or follow them where you will actually see them.',
  status = 'live'
where id = '78a34972-8785-437a-a86e-415cf524fb21' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Independent · Ages 16 plus · Made by someone", "title": "Creating things and getting properly paid", "body": "A ten minute lesson for the two of you, about owning what you make online and getting properly paid for it.", "script": "Start as equals: what has each of you made that you were proud of, and where did it end up? Has either of you ever been paid for creative work, or asked to hand it over for exposure?"}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can protect what I make, understand what I am signing away, and ask to be paid like a professional.", "why": "The internet is full of people who will happily use your work for free. Knowing what you own is the difference between a career and a donation.", "gains": ["I know my work is mine the moment I make it", "I run the rights check before I upload anywhere", "I can agree money in writing before the work starts"]}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Yours the moment you make it", "emoji": "©️", "body": "In the UK, copyright is automatic. The moment you write the song, take the photo or ship the code, it is yours. Nobody registers anything. From there you have two things to sell: a licence, which rents out set uses while you keep ownership, or the copyright itself, which is gone for good once sold. Read every agreement for which one it is.", "script": "Test each other on the difference: licence versus copyright sale, renting out the house versus selling it. Then find one real example, a platform either of you actually uploads to, and see what its terms take."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "The rights check", "emoji": "🔍", "body": "Before your work goes anywhere, a platform, a client, a competition, run the rights check. Three questions. Who owns this after I upload it? What can they do with it without asking me again? What do I get? If the terms cannot answer all three, ask before you upload, or do not upload. Competitions are the classic trap: some claim rights over every entry, including the ones that lose.", "script": "Run the check together on a real competition or platform in front of you now. Finding the answers in the terms once, as a pair, is what makes the habit real."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Paid like a professional", "emoji": "💷", "body": "Money agreed in writing before the work starts, every time, even with friends of friends. An invoice is not scary: your name, their name, what you did, the agreed price, the date. Keep your original files, because they are your proof and your property. And exposure is not a currency. People die of exposure.", "script": "Role play the awkward sentence with each other until it stops being awkward: I would love to do this, and my rate for that is..."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "A clothing brand DMs you: they love your artwork, want to repost it, and ask for the original file. They offer exposure to eighty thousand followers. What is the strong move?", "options": [{"text": "Send the file. Exposure to eighty thousand people has to be worth something", "correct": false, "feedback": "Exposure pays nothing and the original file is your proof of ownership. Plenty of brands bank on makers being too flattered to ask. You are allowed to be flattered and still invoice."}, {"text": "Run the rights check, then reply asking what they will pay and exactly what use they want, in writing", "correct": true, "feedback": "Professional, polite, and it takes one message. A real brand answers it easily. One that vanishes at the mention of payment was never offering anything."}, {"text": "Block them. Any brand sliding into your DMs is a scam", "correct": false, "feedback": "Real commissions genuinely start in DMs. The filter is not where they asked. It is whether they will put money and terms in writing."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "What does it mean to license your work to someone?", "options": [{"text": "They own it now and can do anything with it forever", "correct": false, "feedback": "That is a copyright sale, the other thing entirely. A licence is narrower, and the difference is worth real money."}, {"text": "They rent agreed uses of it, for an agreed time or purpose, while you keep ownership", "correct": true, "feedback": "Exactly. Rent, not sale. The same piece of work can earn again and again, which is how creative careers are actually built."}, {"text": "They can use it however they like as long as they credit you", "correct": false, "feedback": "Credit is a courtesy, not a licence. What they may do with your work is set by the agreement, and credit alone pays for nothing."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["What you make is yours from the moment you make it.", "Run the rights check before your work goes anywhere.", "Exposure is not a currency. Agree money in writing."]}]'::jsonb,
  try_this = 'Before either of you next uploads work anywhere, run the rights check together: who owns it after upload, what can they do with it, and what do you get.',
  status = 'live'
where id = '04122ccf-cd0a-4dd6-9774-ba3fbf376646' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Independent · Ages 16 plus · Private stuff", "title": "Lock it down before it holds your life", "body": "A ten minute lesson for the two of you, about securing an adult digital life before it holds anything worth stealing.", "script": "Open as equals, and be honest: does either of you reuse a password right now? Nearly every adult does. No confessions owed in either direction. Today you fix it together."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can secure my accounts, my data and my money like an adult, starting with the one account that opens all the others.", "why": "Very soon your accounts hold real money, real work and your whole identity. Ten minutes of setup now beats months of clean up after a breach.", "gains": ["I know why my email is the master key to everything", "I have made the master key move on my own accounts", "I can spot the pressure moves scammers use around money"]}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Your email is the master key", "emoji": "🗝️", "body": "Nearly every account you own resets its password through your email. Bank, uni, work, everything. Whoever controls your inbox controls the lot, because the forgot password button is an open door to them. That makes your email not just another account. It is the master key, and it deserves the strongest lock you own.", "script": "Count aloud together: how many accounts would fall if someone held your inbox for one hour? Getting past twenty is normal. That number is the whole argument."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "The master key move", "emoji": "🔐", "body": "The master key move, in order. One: a long unique password on your main email, and three random words beats anything clever. Two: two step verification switched on, so a stolen password alone is useless. Three: recovery details checked, yours and current. Then the bank, then a password manager for everything else, so every door gets its own key and one leaked site no longer opens your whole life.", "script": "Do it now, side by side, each on your own phone. Five minutes each. This is the rare lesson where the homework fits inside the lesson."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Money moves under pressure", "emoji": "⏱️", "body": "Nearly every money scam runs the same engine: urgency plus authority. Your account is compromised, act now, this is the fraud team. Real banks never ask you to move money to a safe account, never ask for full passwords, and never mind you hanging up to call back on the number from your card. The pressure itself is the tell. Anyone rushing your money is reaching for it.", "script": "Swap the scam texts you have both actually received. Spot the engine in each one: where is the urgency, where is the fake authority? Then agree the house rule as equals: big money moves get a second pair of eyes, yours included."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "A text says your bank account is compromised: click the link in the next ten minutes and move your balance to a safe account. What is the strong move?", "options": [{"text": "Click fast. Fraud is time sensitive and this could be real", "correct": false, "feedback": "The countdown is the con. Real banks never ask you to move money to a safe account. The urgency exists to stop you doing exactly what would expose it: pausing and checking."}, {"text": "Ignore the link, open your banking app yourself or call the number on your card, and tell someone what arrived", "correct": true, "feedback": "Exactly right. You went through the front door you trust, not the side door they built, and saying it out loud to someone breaks the isolation every scam depends on."}, {"text": "Reply to the text asking whether it is genuine", "correct": false, "feedback": "That is asking the scammer to vouch for the scam, and any reply confirms your number is live. The checking has to happen on a channel you chose, not one they sent you."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "Why does your email get secured before every other account?", "options": [{"text": "Because email holds the most embarrassing things", "correct": false, "feedback": "Maybe it does, but that is not the reason. The reason is mechanical: every other account trusts your email to confirm who you are."}, {"text": "Because password resets flow through it, so it is the master key to everything else", "correct": true, "feedback": "Exactly. Lock the master key first and a criminal with one of your other passwords hits a wall. Leave it weak and nothing else you secure matters much."}, {"text": "Because email companies make you do it", "correct": false, "feedback": "Nobody makes you. Plenty of inboxes sit behind one weak reused password. That is exactly why inboxes are where attackers aim first."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["Your email is the master key. Lock it first.", "Every door gets its own key. That is what the manager is for.", "Anyone rushing your money is reaching for it."]}]'::jsonb,
  try_this = 'Today you both make the master key move: a long unique password and two step verification on your main email, then work outward from there.',
  status = 'live'
where id = '54ca0ac0-5d1b-4082-af13-8418a790857e' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Independent · Ages 16 plus · People and screens", "title": "Meeting people from the internet, like an adult", "body": "A ten minute lesson for the two of you, about moving an online connection into real life with a plan instead of a hope.", "script": "Trade stories as equals. Most adults have met someone from the internet by now: a date, a buyer, a gaming friend. What made those meetings feel fine, or not? Your own stories carry this lesson better than any rules."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can meet someone from the internet with a plan that protects me, and I know that if a meeting goes wrong the fault is never mine for going.", "why": "Meeting people online is normal adult life now. Dates, flat viewings, buying a bike. The skill is not avoiding it. The skill is doing it with your eyes open and your exits planned.", "gains": ["I treat the first meeting differently from every later one", "I use the first meet plan without feeling awkward about it", "I know telling someone is strength, before and after"]}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Most people are real. Plan for the few who are not", "emoji": "🤝", "body": "Most people you meet online are exactly who they say. But you cannot tell which are which through a screen, however long you have talked, because time chatting is not evidence, it is just time. So the plan is not paranoia and it is not an insult to them. It is a seatbelt. You wear it for every drive, not because every drive crashes.", "script": "Say the seatbelt line to each other and mean it both ways: this plan is what I would want for you, and what I would use myself. It applies at forty as much as at sixteen."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "The first meet plan", "emoji": "📍", "body": "The first meet plan has three parts. A public place with people around, a cafe or a station, never a car or a house. Someone you trust told: who you are meeting, where, and when you will check in. And your own way there and back, so you can leave the moment you want to. A video call first is a fair ask too. Someone real will not mind. Someone who argues with the plan has just told you something useful.", "script": "Build the plan together for a real or imagined first meeting, and agree to be each other''s told person. Write the check in text now so it is one tap when it matters."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Leaving is allowed. Telling is strength", "emoji": "💪", "body": "If anything feels off, you can leave mid coffee with no apology. A feeling is reason enough, and anyone decent will understand. And if a meeting ever goes wrong, hear this clearly: the fault belongs to the person who lied or pushed, never to you for going. Telling a friend, a parent or the police is not an embarrassing confession. It is the strong move, and the people who care about you will only be glad you did.", "script": "Say this part in your own words, steadily, and in both directions: if a meeting ever goes badly for you, I want to know, and there will be no blame here, only backup. Then leave it there. Said once and meant is enough."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "Someone you have talked to for three months suggests finally meeting. They offer to pick you up and drive you to their place. What is the strong move?", "options": [{"text": "Agree. Three months of talking every day means you basically know them", "correct": false, "feedback": "Three months of chat is three months of their side of the story. It is not evidence. The first meeting is where the story gets tested, so it follows the plan whoever they are."}, {"text": "Say you would love to meet, and counter with the first meet plan: a public place, someone told, your own way there and back", "correct": true, "feedback": "Exactly right, and notice it is not a rejection. It is a yes with a seatbelt. How they take the plan tells you more about them than three months of messages did."}, {"text": "Cancel the whole thing. Meeting people from the internet is not worth the risk", "correct": false, "feedback": "Meeting online friends can be one of the best parts of a connected life, and adults do it constantly. The plan exists so you never have to choose between the experience and your safety."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "A first meeting goes badly: the person was nothing like their profile and pushed to move somewhere private. Whose fault is that, and what is the move?", "options": [{"text": "Partly yours, for trusting someone from the internet in the first place", "correct": false, "feedback": "No. Trusting people is not a mistake, and going was not a mistake. The deception was theirs and the fault is theirs, entirely. Blame that lands on the wrong person is what keeps people silent."}, {"text": "The fault is theirs alone, and the move is telling someone you trust straight away", "correct": true, "feedback": "Exactly. The plan already worked: public place, someone knew, you could leave. Telling someone closes the loop and protects the next person too. That is strength, start to finish."}, {"text": "Nobody needs to know, since nothing serious actually happened in the end", "correct": false, "feedback": "You do not owe anyone silence, and near misses are worth saying out loud. The person you tell will not think less of you, and telling keeps the whole plan strong for next time."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["Most people are real. The plan is for the few who are not.", "First meet plan: public place, someone told, your own way home.", "If it goes wrong, the fault is theirs. Telling someone is strength."]}]'::jsonb,
  try_this = 'Agree the first meet plan out loud today, public place, someone told, own way home, so it is already normal before either of you needs it.',
  status = 'live'
where id = '5ae609d8-2a28-45a7-ab67-ceea17ccae02' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Independent · Ages 16 plus · Your name online", "title": "Owning your online record before it is read", "body": "A ten minute lesson for the two of you, about finding what the internet says about you, cleaning it up, and building the record you actually want found.", "script": "Open as equals with a plain question: when did each of you last search your own name? Admissions tutors, employers and dates all do it. Today you get there first."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can audit my online record the way a stranger would, clean up what I would not defend, and deliberately build what I want found.", "why": "You will be searched, by universities, employers and people you meet. The results page is your first impression now, and it is editable if you get there before they do.", "gains": ["I have seen my record the way a stranger sees it", "I can clean up honestly, without faking anything", "I know new true content outranks old content over time"]}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "The logged out look", "emoji": "🔎", "body": "Your own searches flatter you, because results are personalised. So the audit is the logged out look: a private browsing window, then your name in quotes, your name plus your town and school, your usernames, and an image search too. Read the first two pages like a stranger with five minutes and a decision to make. That page is what the world currently has instead of meeting you.", "script": "Do it now, side by side, each on your own name, then swap surprises as equals. The adult often finds odder relics than the teenager does. Everything found is information, never ammunition."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Clean up, then build", "emoji": "🧹", "body": "Clean first: delete or lock anything you would not defend out loud, close dead accounts, untag what misrepresents you. Then build, because an empty result is a wasted page. Publish things you are proud of under your real name: projects, writing, sport, work. Search engines favour fresh and real, so the record you build on purpose rises above the record you left by accident. This is authorship, not image management. Everything you publish stays true.", "script": "Each name one thing to clean and one thing worth building this month, and trade them like commitments between colleagues, not homework set by one of you for the other."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "The logged out look finds an old account full of posts from when you were fourteen. Nothing terrible, but it reads badly now. What is the strong move?", "options": [{"text": "Leave it. Everyone knows people grow out of their fourteen year old selves", "correct": false, "feedback": "People know that in theory, but a stranger with five minutes does not do that maths. You would be trusting them to be generous when you could simply edit."}, {"text": "Delete or lock it, then publish something current you are proud of so the real you rises up the results", "correct": true, "feedback": "Clean, then build. The old account stops speaking for you and the new work starts to. Within months the first page tells your story in your own words."}, {"text": "Make a glowing fake profile under a slightly different spelling to push it down", "correct": false, "feedback": "An invented record collapses at the first question about it, and being caught polishing is worse than the original posts. Build with true things. They hold weight because they hold up."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "Why does the audit happen logged out, in a private window?", "options": [{"text": "Because searching your own name while logged in breaks the terms of service", "correct": false, "feedback": "No rule stops you. The problem is quieter than that: your usual browser gently bends results around you."}, {"text": "Because logged in results are personalised to you, and a stranger sees a different, colder page", "correct": true, "feedback": "Exactly. The logged out look shows you the page an admissions tutor or employer actually gets, and that page is the one worth editing."}, {"text": "Because private windows delete things from the internet as you find them", "correct": false, "feedback": "A private window changes only what you see, never what exists. Removing things happens where they live: the account, the platform, the untag button."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["You will be searched. Get there first.", "The logged out look shows you the stranger''s page.", "Clean up what you would not defend, then build what you want found."]}]'::jsonb,
  try_this = 'Do the logged out look today: search your names in a private window, side by side, and list what a stranger learns in five minutes.',
  status = 'live'
where id = '9dbebfd0-5e42-4bb5-a9c5-a3c36627ded6' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Independent · Ages 16 plus · Feeling good", "title": "Designing your own digital life, on purpose", "body": "A ten minute lesson for the two of you, about choosing your digital habits on purpose before university and work quietly choose them for you.", "script": "Open with the honest audit, both of you: what is the first thing your thumb does when you wake up, and did either of you ever actually decide that? No judgement in either direction. That question is the whole topic."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can design my own digital habits on purpose, instead of running defaults somebody else set for me.", "why": "Soon nobody structures your day for you. The habits you carry into university and work will either be ones you chose or ones that arrived by default. Choosing is a skill, and it starts one setting at a time.", "gains": ["I can tell a default from a decision in my own day", "I have turned at least one default into a decision", "I design my setup to back the life I actually want"]}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Defaults run most lives", "emoji": "⚙️", "body": "Notifications on, autoplay on, phone charging by the bed, every app one thumb away. None of that was your decision. Designers chose it, and you inherited it, the same way everyone did. A default is not evil. It is just a choice someone else made for you, running quietly until you notice it. Most people never audit theirs. That is the whole gap.", "script": "Count your inherited defaults together, phones out, as equals: autoplay, badges, lock screen, bedside charging. Whoever finds the most surprising one wins."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Default or decision", "emoji": "📐", "body": "The move is default or decision. Pick one habit and ask the only question that matters: did I decide this? If yes, keep it with pride, because screens are not the villain and plenty of defaults deserve to stay. If no, decide now: keep it on purpose, change it, or bin it. One default a week, and within a few months every part of your setup is something you chose. That is what a designed digital life means. Not less, necessarily. Chosen.", "script": "Run the question on one habit each, right now, and make the call together. The adult goes first. A young adult watching a parent redesign a real habit of their own learns more than from any rule ever set."}, {"type": "concept", "phase": "teach", "minutes": 2, "heading": "Design for the life you are heading into", "emoji": "🧭", "body": "University and first jobs hand you freedom and take away structure in the same week. The person who has already chosen their sleep, their notifications and the first hour of their day arrives with an advantage nobody can see and everybody feels. You are not designing for who you are this week. You are designing for the person who has to run their own life soon, and who would like to enjoy it.", "script": "Ask each other the forward question as equals: what does your setup need to look like in one year for the life you actually want? The adult answers for their own year too. Work has defaults just as sticky."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "You notice you are watching videos until one in the morning most nights, and you never actually decided to. What is the strong move?", "options": [{"text": "Accept it. Everyone your age is up watching the same stuff", "correct": false, "feedback": "Common is not the same as chosen. The habit picked you, through autoplay and a well fed algorithm. You are allowed to want your own nights back, whatever everyone else is doing."}, {"text": "Run default or decision: choose your real finish time, then set the phone up to back the choice, autoplay off and charging out of reach", "correct": true, "feedback": "That is designing instead of white knuckling. You made the decision once, in daylight, and handed the boring enforcement to your settings. Design beats willpower every single night."}, {"text": "Delete every video app and go completely cold", "correct": false, "feedback": "Purges feel powerful and mostly bounce back within weeks, because nothing was actually decided. A finish time you chose survives. A ban you installed in a 1am fury usually does not."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "What is the difference between a default and a decision?", "options": [{"text": "Defaults are the free settings and decisions are the ones you pay for", "correct": false, "feedback": "Money is not the line. Plenty of paid apps arrive stuffed with defaults, and the best decisions cost nothing but a moment of noticing."}, {"text": "A default is a choice someone else made for you, still running. A decision is one you examined and made on purpose", "correct": true, "feedback": "Exactly. The setting can even end up identical. What changes is the author. A designed digital life is just your own decisions, all the way down."}, {"text": "Defaults are always bad and decisions are always good", "correct": false, "feedback": "Plenty of defaults are worth keeping, and people make poor decisions daily. The point is not that defaults are the villain. It is that your setup should be authored by you."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["A default is a choice someone else made for you.", "Ask default or decision, one habit at a time.", "Design the setup now. Your future week will run on it."]}]'::jsonb,
  try_this = 'Run default or decision on one habit each today, decide on purpose what happens to it, and compare choices tomorrow.',
  status = 'live'
where id = '95a9ae19-2763-4df6-bc93-fcafb52efdc4' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Shaper · Ages 13 to 15 · AI and you", "title": "Using AI to learn, not to skip learning", "body": "A ten minute lesson for you and your teenager, about using AI to get smarter instead of just getting finished.", "script": "Open honestly: ask what they actually use AI for, homework included, and promise no telling off whatever the answer. This lesson only works if the truth is safe to say."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can use AI to understand something, and prove to myself that I really do.", "why": "AI can write your homework in seconds. But the grade was never the point. The point is what your brain can do when the screen is off.", "gains": ["I know the difference between using AI and hiding behind it", "I have the explain it back test to check I really learned", "I can be honest about how I used AI"]}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🧠", "heading": "Borrowed answers, borrowed brain", "body": "If AI writes it and you copy it, the work gets done but you stay exactly where you were. In the test, the interview, the moment it matters, the AI is not there. Only what you actually understand turns up with you.", "script": "Say it straight: I am not worried about you cheating the school. I am worried about you cheating yourself. Ask when AI last saved them time, and whether they could still do that task alone."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🗣️", "heading": "The explain it back test", "body": "Use AI all you like to learn. Then close the screen and explain the idea back in your own words, out loud or on paper. If you can, the learning is yours now. If you cannot, you have a summary, not an understanding. Go back and ask the AI better questions until you can.", "script": "Try it right now on something small. Ask them to explain one thing they learned this week with no screen in reach. Cheer the wobbly bits, that is where learning shows itself."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🎯", "heading": "Ask like a learner", "body": "Copiers ask AI for the answer. Learners ask AI to explain, to quiz them, to mark their attempt. Same tool, opposite results. Try this: explain it like I am fourteen, then give me three questions to test me, then mark my answers.", "script": "Build one learner prompt together for a real piece of homework due this week. The habit sticks when it saves them effort on something that actually counts."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "An essay is due tomorrow and AI could write the whole thing in a minute. What is the strong move?", "options": [{"text": "Let AI write it and change a few words so it sounds like you", "correct": false, "feedback": "That gets the essay in, but the skill it was building never arrives. And teachers spot borrowed voices faster than you would think."}, {"text": "Use AI to explain the topic and quiz you, then write it yourself and run the explain it back test", "correct": true, "feedback": "That is the tool working for you. The essay is yours, the understanding is yours, and tomorrow you can defend every line of it."}, {"text": "Refuse to touch AI at all so it stays fair", "correct": false, "feedback": "You do not have to boycott the tool. Used as a tutor it is brilliant. The line is who does the thinking, not whether AI is involved."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "How do you know a piece of learning is really yours?", "options": [{"text": "The homework got a good grade", "correct": false, "feedback": "A grade can be earned by a borrowed answer. It measures the page, not your brain."}, {"text": "You can explain it back in your own words with the screen closed", "correct": true, "feedback": "Exactly. The explain it back test is the proof. If it survives without the screen, it is yours."}, {"text": "You spent a long time on it", "correct": false, "feedback": "Time helps, but you can spend an hour copying. The test is what you can explain, not how long you sat there."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["AI can hand you an answer, but it cannot hand you understanding.", "Close the screen and explain it back. That is the test.", "Use AI like a tutor and you get stronger every time."]}]'::jsonb,
  try_this = 'Tonight, pick one piece of homework, use AI only to explain and quiz, then do the explain it back test with the screen closed.',
  status = 'live'
where id = 'd032a856-8280-42c2-a009-66c0e1b4f4b7' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Shaper · Ages 13 to 15 · When it turns unkind", "title": "Screenshots, shame and standing firm", "body": "A ten minute lesson for you and your teenager, about surviving a public moment online and helping someone else survive theirs.", "script": "Ease in gently: ask if they have ever seen a screenshot go round about someone. Listen first. Make clear this lesson is a plan for a bad day, not an accusation about anything."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can get through a screenshot moment without making it worse, and I know exactly who to tell.", "why": "Almost everyone gets an embarrassing moment shared at some point. It feels enormous and permanent. It is neither, and there is a plan for it.", "gains": ["I know the shame belongs to the person who shared it, not to me", "I have the save, step back, tell plan ready", "I know how to help a friend in the middle of theirs"]}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "⚖️", "heading": "Whose shame is it?", "body": "If someone screenshots a private message or an awkward moment and shares it to embarrass you, they did the wrong thing. Not you. Being trusted with something and turning it into a weapon says everything about them and nothing about you. Hold on to that fact when the laughing feels loudest.", "script": "Say this plainly: if this ever happens to you, you will not be in trouble with me. The person who shared it made the choice. I want to be the first person you come to, not the last."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🛟", "heading": "Save, step back, tell", "body": "First, save the evidence: screenshot the post and note who shared it. Second, step back: do not reply, do not post back, do not perform for the audience, because reaction is what keeps it alive. Third, tell a trusted adult the same day and report the post on the platform. If a private image is involved, an adult can help you report it to CEOP, the UK police team built for exactly this. None of that is weakness. It is the strongest set of moves there is.", "script": "Walk the three steps slowly. Ask which one they think would be hardest. For most teenagers it is the tell step. Agree now who their tell person is, you or another adult they trust, so the choice is already made before a bad day."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🤝", "heading": "Be the friend who ends it", "body": "When it is someone else in the screenshot, you have real power. Do not share it on, even as a joke, because every share is a fresh hit. Send the person one private message: I saw it, it is not a big deal to me, are you okay? One kind message outweighs fifty laughing ones.", "script": "Ask them: what would you want a friend to send you in that moment? Whatever they answer, that is the message they should send when it is someone else''s turn."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "A screenshot of your awkward message is going round the group chats and people are laughing. What is the strong move?", "options": [{"text": "Post a comeback so people laugh with you instead", "correct": false, "feedback": "Performing for the audience feels like taking control, but it feeds the story and keeps it alive another week. Step back instead."}, {"text": "Save the evidence, step back from replying, and tell your trusted adult today", "correct": true, "feedback": "That is save, step back, tell, done in order. It ends the story faster and puts real help on your side."}, {"text": "Delete everything and tell nobody so it dies quietly", "correct": false, "feedback": "Telling nobody leaves you carrying it alone, and the evidence you deleted was your best protection. The tell step is what makes the plan strong."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "When a private message gets screenshotted and shared to embarrass someone, whose fault is it?", "options": [{"text": "The person who wrote the message, they should have known better", "correct": false, "feedback": "Trusting someone is not a mistake. Turning that trust into a weapon was the choice, and it was not theirs."}, {"text": "The person who shared it, because they turned trust into a weapon", "correct": true, "feedback": "Exactly. The shame belongs to the sharer. The person in the screenshot did nothing wrong."}, {"text": "Both of them equally", "correct": false, "feedback": "Splitting the blame sounds fair but it is not true. One person chose to embarrass another. That is where the fault sits."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["If someone shares your moment to shame you, the shame is theirs, not yours.", "Save, step back, tell. In that order, on the same day.", "One kind private message can outweigh fifty laughing shares."]}]'::jsonb,
  try_this = 'Agree tonight who your teenager''s tell person is, so save, step back, tell is ready before it is ever needed.',
  status = 'live'
where id = '2aefe7bd-a2de-4db7-8508-d129f37373fb' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Shaper · Ages 13 to 15 · Being you", "title": "Who are you online?", "body": "A ten minute lesson for you and your teenager, about running different accounts while staying one honest person.", "script": "Start curious, not suspicious: ask how many accounts they have across their apps and what each one is for. Main, private, group ones. No judgement. Most teenagers run several, and there are good reasons to."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can run different accounts for different audiences and still be one person I recognise.", "why": "Having a main account and a private one is normal. The risk is not the number of accounts. It is when one of them starts belonging to someone you would not want to be.", "gains": ["I know why different accounts for different audiences is normal", "I have the one person test for any post on any account", "I can spot when an account is pulling me away from myself"]}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🎭", "heading": "Different rooms, same you", "body": "You already have different versions of you: how you talk to your grandad, your mates, your teacher. That is not fake, that is social skill. Accounts work the same way. A main for everyone, a private one for close friends. Different rooms are fine. It is the same person walking between them that matters.", "script": "Share your own version: how you differ at work and at home, and what stays constant. It makes the point that adjusting to an audience is a skill, not a lie."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🪞", "heading": "The one person test", "body": "Before you post on any account, ask one question: if the people from my other accounts saw this, would I still stand behind it? You do not need them to see it. You need to be able to own it. If a post only works because nobody knows it is you, that is the warning light, not the account name.", "script": "Make it concrete: ask them to picture their most recent post on their most private account, and whether they would own it if it surfaced. No need to show you anything. The point is the private check, not an inspection."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🚦", "heading": "When an account starts driving", "body": "Watch for the drift: an account where you are meaner, or fake happier, or performing a person you do not actually like. Accounts train you with likes, and they can train you into someone else a little at a time. If one of your accounts fails the one person test week after week, the strong move is to change how you use it, or close it.", "script": "Ask which account they like themselves most on, and least on. That second answer is the interesting one. Talk about what that account rewards them for."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "On your private account, the jokes that get the most laughs are ones you would be ashamed of on your main. What is the strong move?", "options": [{"text": "Keep going, it is a private account, that is what it is for", "correct": false, "feedback": "Private controls who sees it, not who you become. If the jokes fail the one person test week after week, the account is training you into someone else."}, {"text": "Run the one person test, and change what you post there so you can stand behind it anywhere", "correct": true, "feedback": "That is the test doing its job. You can keep the account and the audience. You just take yourself with you into it."}, {"text": "Delete every account and stay offline", "correct": false, "feedback": "You do not have to vanish to stay honest. Different accounts are fine. The fix is passing the one person test, not disappearing."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "What does the one person test actually check?", "options": [{"text": "Whether your parents can see everything you post", "correct": false, "feedback": "It is not about being watched. It is a check you run on yourself, for yourself."}, {"text": "Whether you would stand behind the post if your other audiences saw it", "correct": true, "feedback": "Exactly. Own it anywhere, even if you never show it everywhere. One person, many rooms."}, {"text": "Whether the post will get enough likes", "correct": false, "feedback": "Likes measure the audience, not you. The test asks what you can stand behind, not what will score."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["Many accounts is normal. Many selves is the thing to watch.", "Run the one person test before you post, on every account.", "If a post only works when nobody knows it is you, that is your warning light."]}]'::jsonb,
  try_this = 'Ask your teenager which account they like themselves most on and least on, then run the one person test together on one recent post.',
  status = 'live'
where id = '9cf04cb2-b75e-4631-a057-8a44dbcf04a1' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Shaper · Ages 13 to 15 · True or not", "title": "Deepfakes and doctored truth", "body": "A ten minute lesson for you and your teenager, about what to do now that seeing is no longer proof.", "script": "Open with a wondering question: have you ever seen a video and only later found out it was fake? What gave it away, or what fooled you? Swap stories both ways. Adults get fooled too."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can check a video or image before I believe it or share it, because seeing is not proof anymore.", "why": "AI can now make video and audio of things that never happened, of famous people and of ordinary people. Your eyes alone cannot referee that. Your method can.", "gains": ["I know why a convincing video is not proof by itself", "I have the second source rule before believing or sharing", "I know what to do if a fake is ever made about me or someone I know"]}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "👁️", "heading": "Seeing used to be believing", "body": "For your grandparents, video was solid evidence. Now AI can fake a face, a voice, a whole scene, well enough to fool millions. Some fakes are built to make you angry, scare you, or scam you. Some target ordinary people, teenagers included. If a fake is ever made about you, you have done nothing wrong: tell a trusted adult, report it to the platform, and for anything sexual report it to CEOP. The feeling a clip gives you is not evidence of anything.", "script": "Underline the last line together: the stronger the feeling a clip triggers, the more it deserves checking, because outrage is exactly what fakes are built to farm. And say the reporting line out loud so it is heard in your voice, not just read."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🔍", "heading": "The second source rule", "body": "Before you believe or share a dramatic clip, find a second, independent source. Search the claim in your own words. Check whether any proper news outlet carries it. Look for the original post, the date, the place. If the only source is the clip itself, treat it as unproven, no matter how real it looks. Thirty seconds of checking beats a week of being wrong.", "script": "Run it live: pick a wild clip or claim either of you has seen this week and do the thirty second check together. The method matters more than the verdict."}, {"type": "scenario", "phase": "teach", "minutes": 2, "handle": "@breaking_clipz", "avatar": "🎬", "meta": "Shared 41,208 times · posted 2 hours ago", "text": "LEAKED footage of a famous footballer insulting his own fans 😱 share this before it gets deleted!!", "prompt": "Before you even press play: what do you notice about how this post is written? What is it trying to make you feel, and what would the second source rule do with it?"}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "A shocking clip of a celebrity is flying round the group chat and everyone is sharing it. What is the strong move?", "options": [{"text": "Share it fast, it will be old news in an hour", "correct": false, "feedback": "Speed is how fakes spread. Every quick share lends the clip your name, and unsharing is much harder than not sharing."}, {"text": "Run the second source rule: search the claim, look for a proper outlet, then decide", "correct": true, "feedback": "Thirty seconds of checking before your name goes near it. That is the rule working exactly as built."}, {"text": "Assume it is real because it looks completely real", "correct": false, "feedback": "Looking real is the one thing fakes are best at. That is why the second source, not your eyes, makes the call."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "Why is a convincing video not proof by itself anymore?", "options": [{"text": "Because all videos online are fake now", "correct": false, "feedback": "Most videos are real. The problem is you cannot tell which by looking, so checking is the referee, not your eyes."}, {"text": "Because AI can fake faces, voices and whole scenes well enough to fool anyone", "correct": true, "feedback": "Exactly. When looking real can be manufactured, proof has to come from checking, not seeing."}, {"text": "Because famous people deny everything anyway", "correct": false, "feedback": "Denials are not the issue. The issue is that footage itself can be manufactured, so it needs a second source."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["If a clip makes you feel a lot, check it a lot.", "The second source rule: no second source, no share.", "A fake about you is never your shame. Tell an adult and report it."]}]'::jsonb,
  try_this = 'Pick one dramatic clip from this week''s feeds and run the second source rule on it together, timing the thirty seconds.',
  status = 'live'
where id = '4b6ebcb0-ceae-437c-a5c2-87b3aa7ef64c' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Shaper · Ages 13 to 15 · Made by someone", "title": "Your work has value", "body": "A ten minute lesson for you and your teenager, about protecting what they make and respecting what others made.", "script": "Start with pride, not rules: ask what they have made lately that they are quietly pleased with. An edit, a track, a drawing, a build, a video. This lesson is about that stuff being worth protecting."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can protect my own work online and use other people''s work fairly.", "why": "Everything you post that you made, edits, art, music, videos, jokes, is real work with real value. People take it every day, mostly because makers do not know their work is theirs.", "gains": ["I know my creations belong to me from the moment I make them", "I have the keep, credit, ask habit for my work and other people''s", "I know what to do when someone takes my work"]}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "©️", "heading": "You own it the moment you make it", "body": "In the UK, the moment you create something original, a video, a track, a drawing, a photo, copyright is yours automatically. No form, no fee, no age limit. Posting it does not give it away, though an app''s terms usually gain a licence to show it. Made by you means owned by you. That is worth actually knowing.", "script": "This surprises most adults too. Ask: did you know you already own copyright in every original thing you have posted? Watch that land."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🧰", "heading": "Keep, credit, ask", "body": "Three habits protect makers, including you. Keep: save your original files and drafts, they are your proof of authorship. Credit: put your name or handle on work you share, and name the makers whose work you use. Ask: before you repost someone''s art or use their work beyond what the app allows, send them a message. It takes one message, and makers usually say yes to people who ask.", "script": "Pick one thing they have made and do the keep step right now: check the original file exists somewhere that is theirs, not only inside one app."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🛡️", "heading": "When someone takes your work", "body": "If someone reposts your work as theirs, you have moves. Message once, calmly, asking for credit or removal. Use the app''s report tool. Every big platform has a copyright report, and your kept originals are your evidence. If a company is using your work, a trusted adult can help you push properly. Calm and documented beats furious and empty.", "script": "Ask if this has ever happened to them or a friend, a stolen edit or a reposted clip. Map what they did then against these moves now."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "Your edit gets reposted by a bigger account with your name cropped off, and it is getting thousands of views. What is the strong move?", "options": [{"text": "Blast them in the comments so everyone knows they stole it", "correct": false, "feedback": "Fury feels fair, but it hands them a drama to win. Calm and documented is the version that actually gets results."}, {"text": "Message once asking for credit or removal, then use the copyright report with your kept original as proof", "correct": true, "feedback": "One calm message, then the report tool, with your original as evidence. That is how makers actually win these."}, {"text": "Let it go, once it is posted it belongs to the internet", "correct": false, "feedback": "That is the myth that keeps makers unpaid. Your work stayed yours when they took it, and the report tools exist exactly for this."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "When does your original work become legally yours?", "options": [{"text": "When you register it and pay a fee", "correct": false, "feedback": "No form, no fee. In the UK copyright is automatic. Registration is not the trigger."}, {"text": "The moment you make it", "correct": true, "feedback": "Exactly. Made by you means owned by you, from the first save. That is why keeping originals matters."}, {"text": "Only when you turn eighteen", "correct": false, "feedback": "There is no age limit on copyright. A maker at thirteen owns their work the same as a maker at thirty."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["Made by you means owned by you, from the moment you make it.", "Keep, credit, ask. For your work and for everyone else''s.", "Calm and documented beats furious and empty, every time."]}]'::jsonb,
  try_this = 'Tonight, do the keep step: find the original files of your teenager''s three favourite creations and save them somewhere that belongs to them.',
  status = 'live'
where id = 'e15c3b28-986b-42cb-afd7-8dc2acd6d8b6' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Shaper · Ages 13 to 15 · Private stuff", "title": "Scams aimed at teenagers", "body": "A ten minute lesson for you and your teenager, about the scams built for teenagers and the plan that beats every one of them.", "script": "Set the tone before anything else: nothing in this lesson is an accusation, and nothing they ever tell you about this stuff will get them in trouble. Scammers rely on silence. This lesson is how your family takes silence off the table."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can spot the pressure moves scammers use on teenagers, and I know the plan if one ever reaches me.", "why": "Scammers target teenagers on purpose, with fake offers, fake friends and threats. Not because teenagers are silly, but because scammers bet they will stay silent. The plan beats them because it breaks the silence.", "gains": ["I can spot the three pressure moves scams use", "I know a person targeted by a scam has done nothing wrong", "I have stop, tell, report ready, including CEOP"]}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🎯", "heading": "Built for teenagers on purpose", "body": "Some scams are aimed straight at your age group. Fake sponsorship and trainer deals. Fake modelling or gaming offers. Money flips that need your bank details. And the cruellest one: someone builds trust, maybe flirts for weeks, asks for a private image, then threatens to send it to everyone you know unless you pay. That one has a name, sextortion, and it is run by organised criminals who do this to thousands of teenagers. It happens to boys as often as girls, and the person targeted has done nothing wrong.", "script": "Keep your voice steady here. This is the slide that matters most. Say: I know this stuff exists, and if it ever reaches you, you will not be in trouble and I will not panic. You are naming it calmly so it is discussable in your house."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "⏱️", "heading": "The three pressure moves", "body": "Every scam leans on the same three moves. Hurry: decide now, the offer expires, or else happens tonight. Secrecy: do not tell anyone, keep this between us. Shame: you will be in trouble, everyone will see, this is your fault. Real people and real offers survive slowness, openness and daylight. The moment a message uses hurry, secrecy or shame, you are not in a conversation. You are in a script.", "script": "Ask them to find the three moves in any scam or dodgy message they have seen. Hurry, secrecy and shame are easy to spot once named, and naming them is the vaccine."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🛟", "heading": "Stop, tell, report", "body": "If a scam reaches you, even if you already replied, even if you already sent something: you have done nothing wrong. The wrong was done to you. Stop: no more replies, no paying, no sending anything more, because paying or complying never ends it, it only proves the pressure works. Tell: a trusted adult, today, whatever the message threatened, and keep the messages as evidence. Report: block and report in the app, and for anything involving private images or an adult contacting you, report to CEOP at ceop.police.uk, the UK police team built for this. They believe you and they know exactly what to do.", "script": "Read the first line to them word for word: even if you already sent something, you have done nothing wrong and the plan still works. Teenagers stay silent because they think one mistake disqualifies them from help. Kill that idea tonight."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "Someone you have chatted with for weeks suddenly threatens to share a private image unless you pay by tonight. What is the strong move?", "options": [{"text": "Pay, it is the fastest way to make it go away", "correct": false, "feedback": "Paying never ends it. It tells them the pressure works, and the demands grow. That is how the scam is built, and none of it is your fault."}, {"text": "Stop replying, tell a trusted adult today, and report it to CEOP with the messages saved", "correct": true, "feedback": "Stop, tell, report. You have done nothing wrong, the crime is entirely theirs, and CEOP handles this exact situation every single day."}, {"text": "Delete everything and hope they were bluffing", "correct": false, "feedback": "Silence is what the scam counts on, and the saved messages were your evidence. Telling an adult is the move that actually ends it."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "A message is pushing hurry, secrecy and shame all at once. What does that combination tell you?", "options": [{"text": "The offer must be exclusive and about to expire", "correct": false, "feedback": "That is exactly what the hurry move wants you to feel. Real offers survive slowness and daylight."}, {"text": "You are in a script, not a conversation, and stop, tell, report is the answer", "correct": true, "feedback": "Exactly. Hurry, secrecy and shame are the fingerprint of a scam. Name the moves, then run the plan."}, {"text": "You should negotiate to buy yourself time", "correct": false, "feedback": "Negotiating keeps you inside their script. Stepping out of the conversation and telling an adult is what breaks it."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["Scams need silence. Telling someone breaks them.", "Hurry, secrecy and shame are the fingerprint. Name them and you are free of them.", "Stop, tell, report. Whatever already happened, you have done nothing wrong."]}]'::jsonb,
  try_this = 'Say the sentence out loud tonight: whatever a message ever threatens, you will never be in trouble for telling me, then practise spotting hurry, secrecy and shame in one scam message.',
  status = 'live'
where id = '72d7da1b-f28f-4144-b302-3995b9799f7a' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Shaper · Ages 13 to 15 · People and screens", "title": "Relationships, pressure and phones", "body": "A ten minute lesson for you and your teenager, about pressure inside private messages and why no is a complete answer.", "script": "Open with the wide version, not the personal one: ask what pressure looks like in messages among their year group generally. Keeping it about the year group makes it safe to talk about."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can spot pressure in private messages, hold my no, and know exactly what to do if someone will not accept it.", "why": "The hardest pressure does not come from strangers. It comes wrapped in affection: if you liked me you would. Consent does not switch off because a conversation is private or a person is nice.", "gains": ["I know consent applies in messages the same as in person", "I have the no test to tell asking from pressuring", "I know the plan when someone keeps pushing, including who to tell"]}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "💬", "heading": "Pressure wearing affection", "body": "Pressure in messages rarely sounds like a villain. It sounds like: everyone does it, you would if you cared, I already sent you one, do not be boring. Sometimes it is asking for a private image. Sometimes it is demanding passwords, location, or constant replies as proof of love. Affection that arrives with a demand attached is not affection doing the talking.", "script": "Name the specific one calmly: pressure to send images is common at this age, inside relationships and outside them. Say once, clearly: being asked is never your fault, and no is always available, whoever is asking."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🧭", "heading": "The no test", "body": "Here is the test that sorts asking from pressuring: a real request survives a no. Say no and watch what happens. A person who was asking accepts it and nothing changes. A person who was pressuring punishes it: sulking, guilt, threats, asking again tomorrow. That reaction is your answer about them, not about you. You never owe anyone an image, a password, or proof of love.", "script": "Rehearse an actual sentence together so it exists before it is needed. Something like: no, and if you ask again that tells me something. Let them build their own version in their own words."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🛟", "heading": "When no does not land", "body": "If someone keeps pushing after your no, the situation has changed and so does the plan. Save the messages. Tell a trusted adult, even if you care about the person, even if it feels disloyal, because pressure that ignores a no is not a private matter anymore. If anyone shares or threatens to share a private image, or an adult is doing the asking, report it to CEOP at ceop.police.uk. Whatever you said or sent before that moment, the wrong belongs to the person applying the pressure, not to you.", "script": "This is the line to say in your own voice: even if you sent something, even if you said yes before, you can still come to me and you will not be in trouble. The earlier they hear it, the earlier they can use it."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "Someone you really like keeps saying: if you cared about me you would send a photo. What is the strong move?", "options": [{"text": "Send it, they are your partner and it stays between you two", "correct": false, "feedback": "Caring is not proved by complying, and screens make private a promise nobody can keep. A request with a guilt trip attached has already failed the no test."}, {"text": "Say no, and if the pressure continues, save the messages and tell a trusted adult", "correct": true, "feedback": "That is the no test working. A real request survives a no. Pressure that keeps coming stops being a private matter, and telling an adult is strength."}, {"text": "Keep changing the subject and hope they stop asking", "correct": false, "feedback": "Dodging leaves the pressure in place and puts all the work on you. A clear no gives their reaction the chance to tell you the truth."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "What does the no test actually reveal?", "options": [{"text": "Whether you are brave enough to say no", "correct": false, "feedback": "The test was never measuring you. Your no counts however it comes out. The test measures them."}, {"text": "How the other person handles a no, which tells you if they were asking or pressuring", "correct": true, "feedback": "Exactly. A real request survives a no. The reaction after your no is the honest information."}, {"text": "Whether the relationship is worth keeping", "correct": false, "feedback": "It is not a verdict on the whole relationship in one go. It is smaller and sharper: was that a request, or was it pressure?"}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["A real request survives a no. That is the no test.", "You never owe anyone an image, a password, or proof of love.", "If a no gets punished, save it, tell an adult, and for images report to CEOP."]}]'::jsonb,
  try_this = 'Help your teenager write their own no sentence tonight, so the no test is ready in their own words before anyone tests it.',
  status = 'live'
where id = 'ce25301d-3a67-4953-bdf9-1e519a74e42f' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Shaper · Ages 13 to 15 · Your name online", "title": "Reputation and the long game", "body": "A ten minute lesson for you and your teenager, about reading your own posts the way a sixth form, a coach or an employer will.", "script": "Open with a real question: have you ever looked yourself up the way a stranger would? Offer to do it together later. Not as a gotcha, as reconnaissance."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can read my posts through the eyes of the people who will one day decide something about me.", "why": "In the next few years, real people will look you up: sixth forms, employers, coaches, teams. They will not know your context or your jokes. They will only see the posts. You get to choose what the posts say.", "gains": ["I know who actually looks people up and when", "I have the three readers test to run before I post", "I know how to tidy what is already out there"]}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🔎", "heading": "The people who will look you up", "body": "Sixth forms and colleges check applicants. Employers check for weekend jobs, apprenticeships and beyond. Sports clubs and academies check players before signing them. They are not hunting for perfection. They are asking one question: is this someone we want representing us? A feed of ordinary life, interests and humour passes easily. A feed of cruelty or recklessness raises a question you are not in the room to answer.", "script": "Make it real with one true story from your own world, a hire, a team, a course, where what someone had posted mattered either way. True and specific beats scary and vague."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "👓", "heading": "The three readers test", "body": "Before posting anything you are unsure about, picture three readers seeing it in five years: a sixth form tutor, a coach or team captain, and a boss you would want to work for. Not because they own you, but because future you will be standing in front of them. If the post fails all three, it is not worth what it costs. If it passes, post away. The test takes ten seconds and it is yours for life.", "script": "Stress what the test is not: it is not be boring, and it is not never joke. Ask them for an example of a post that is funny and still passes all three readers. There are millions."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🧹", "heading": "Tidying the trail", "body": "Your past posts are not a life sentence. Set an hour, scroll your own profiles as a stranger would, and run the three readers test backwards. Delete or archive what fails. Untag what you would not want found. Old accounts you never use can go entirely. This is not hiding who you are. It is choosing your own story instead of leaving it to whatever you posted at eleven.", "script": "Offer to do your own tidy at the same time, on your own profiles. Doing it alongside them turns an inspection into a shared habit."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "You are about to post a savage joke about a teacher and it will definitely get laughs tonight. What is the strong move?", "options": [{"text": "Post it, laughs tonight are guaranteed and the future is ages away", "correct": false, "feedback": "The laughs expire tonight. The post does not. It waits, findable, for readers who were never in on the joke."}, {"text": "Run the three readers test, and if it fails, find the version of funny that passes", "correct": true, "feedback": "Ten seconds against three readers. Funny that passes the test costs you nothing later, and there is always a version that passes."}, {"text": "Post it on your private account where nobody important will see", "correct": false, "feedback": "Screenshots do not respect account settings. Anything posted can travel, so the test applies everywhere, not just on main."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "What are people actually asking when they look you up before offering you a place or a job?", "options": [{"text": "Whether your feed is perfect and serious", "correct": false, "feedback": "Nobody expects a fifteen year old''s feed to look like a CV. Ordinary life and humour pass easily."}, {"text": "Whether you are someone they would want representing them", "correct": true, "feedback": "Exactly. It is one question about character. The three readers test lets you answer it before they ever ask."}, {"text": "Whether you have enough followers to matter", "correct": false, "feedback": "Follower counts are not the question. The question is character, and it is answered by what you post, not how many watch it."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["Real people will look you up. The posts answer for you.", "Run the three readers test: tutor, coach, boss, ten seconds.", "Your past posts are editable. Choose your own story."]}]'::jsonb,
  try_this = 'Set a timer for one hour this week and do a profile tidy together, running the three readers test backwards over old posts.',
  status = 'live'
where id = '6699054e-f0fe-4e6b-b8c9-b9eee25ca531' and status = 'stub';

update lessons set
  slides = '[{"type": "title", "phase": "starter", "minutes": 1, "eyebrow": "Shaper · Ages 13 to 15 · Feeling good", "title": "Sleep is not optional", "body": "A ten minute lesson for you and your teenager, about keeping nine hours of sleep when the phone wants them all.", "script": "Start with honesty about yourself: admit the last time your own phone kept you up too late. Going first buys you the right to talk about theirs."}, {"type": "objective", "phase": "starter", "minutes": 1, "outcome": "I can protect about nine hours of sleep on school nights, with a plan the phone cannot argue with.", "why": "Your body does its growing, your brain files the day, and your mood resets, all while you sleep. Teenagers need about nine hours for that work. The phone is built to take them, one more video at a time.", "gains": ["I know what nine hours actually buys me", "I have the parking spot plan for school nights", "I know why willpower at midnight is the wrong tool"]}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🌙", "heading": "What sleep is actually doing", "body": "Sleep is not switching off. It is the shift where your brain files what you learned, your body grows and repairs, and tomorrow''s mood gets set. Short sleep shows up as worse mood, worse memory, worse skin, worse football. Teenagers need about nine hours a night for the full shift. Nobody performs well as the six hour version of themselves. They just stop noticing what the nine hour version felt like.", "script": "Ask what time they would need to be asleep to get nine hours before their alarm. Do the sum together out loud. The answer usually lands harder than any lecture."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🥱", "heading": "Midnight you is not the decider", "body": "Apps are built by teams whose whole job is one more video, and they are best at it late, when your tired brain is worst at stopping. Willpower at midnight is a fair fight for nobody. So do not fight at midnight. Decide earlier, while deciding is easy, and put the phone physically elsewhere so midnight you does not get a vote.", "script": "This reframe helps teenagers because it is not an insult: it is not that you are weak, it is that nobody wins that fight at midnight, including adults. Design beats willpower."}, {"type": "concept", "phase": "teach", "minutes": 2, "emoji": "🅿️", "heading": "The parking spot", "body": "Pick a spot outside the bedroom, a shelf, a drawer, the kitchen counter, and a time on school nights. At that time, every phone in the house parks there and charges there, including the adult phones. Alarm problem? A cheap alarm clock solves it. The rule has no exceptions to argue about, which is exactly what makes it easy. The phone sleeps in its spot. You sleep in yours.", "script": "Negotiate the two details tonight, the spot and the time, and agree it applies to your phone too. A rule the adults are inside is a rule. A rule they are outside is a punishment, and teenagers can tell the difference instantly."}, {"type": "choice", "phase": "practise", "minutes": 2, "question": "It is midnight, school tomorrow, and the next episode is sitting there ready. What actually protects your nine hours?", "options": [{"text": "Trusting yourself to stop after one more", "correct": false, "feedback": "Midnight you against an autoplay button is a fair fight for nobody, adults included. That is not weakness, it is why the plan exists."}, {"text": "Having parked the phone at its spot hours ago, so the fight never happens", "correct": true, "feedback": "Exactly. The parking spot wins the midnight fight at nine in the evening, while deciding is still easy."}, {"text": "Watching in bed but with the brightness turned down", "correct": false, "feedback": "Dimmer light helps a little, but the episode still takes the hour, and the hour was the whole point."}]}, {"type": "choice", "phase": "prove", "minutes": 2, "question": "Why does the parking spot work better than willpower?", "options": [{"text": "Because it punishes you for wanting your phone", "correct": false, "feedback": "It is not a punishment, and wanting your phone is normal. It is a design that makes the good choice the easy one."}, {"text": "Because it makes the decision early and puts the phone out of reach before you are tired", "correct": true, "feedback": "Exactly. Decide once, while deciding is easy, and midnight you never has to fight at all."}, {"text": "Because phones stop working properly at night", "correct": false, "feedback": "The phone works fine at midnight. It is your stopping power that fades, and the plan covers for that."}]}, {"type": "digi", "phase": "close", "minutes": 1, "heading": "DiGi says", "lines": ["Nine hours is not lazy. It is where your brain and body do the work.", "Nobody beats an autoplay button at midnight. Design beats willpower.", "Park the phone, every phone, same spot, same time. Then sleep is easy."]}]'::jsonb,
